export function getNode(
  graph: CodeGraph,
  entityId: string,
): GraphEntity | undefined {
  return graph.nodes.get(entityId);
}

export function getOutgoing(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphRelationship[] {
  const edges = graph.outgoing.get(entityId) ?? [];

  if (!relationshipTypes || relationshipTypes.length === 0) {
    return edges;
  }

  return edges.filter((edge) =>
    relationshipTypes.includes(edge.type),
  );
}

export function getIncoming(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphRelationship[] {
  const edges = graph.incoming.get(entityId) ?? [];

  if (!relationshipTypes || relationshipTypes.length === 0) {
    return edges;
  }

  return edges.filter((edge) =>
    relationshipTypes.includes(edge.type),
  );
}

export function getNeighbors(
  graph: CodeGraph,
  entityId: string,
  relationshipTypes?: RelationshipType[],
): GraphEntity[] {
  const neighborIds = new Set<string>();

  const outgoing = getOutgoing(
    graph,
    entityId,
    relationshipTypes,
  );

  const incoming = getIncoming(
    graph,
    entityId,
    relationshipTypes,
  );

  for (const edge of outgoing) {
    neighborIds.add(edge.targetId);
  }

  for (const edge of incoming) {
    neighborIds.add(edge.sourceId);
  }

  const neighbors: GraphEntity[] = [];

  for (const id of neighborIds) {
    const entity = graph.nodes.get(id);

    if (entity) {
      neighbors.push(entity);
    }
  }

  return neighbors;
}

export function traverseGraph(
  graph: CodeGraph,
  startEntityId: string,
  options: TraverseOptions = {},
): TraversalResult[] {
  const maxDepth = options.maxDepth ?? 2;

  const visited = new Set<string>();
  const results: TraversalResult[] = [];

  const queue: Array<{
    entityId: string;
    depth: number;
    via?: GraphRelationship;
  }> = [
      {
        entityId: startEntityId,
        depth: 0,
      },
    ];

  while (queue.length > 0) {
    const current = queue.shift()!;

    if (visited.has(current.entityId)) {
      continue;
    }

    visited.add(current.entityId);

    const entity = graph.nodes.get(current.entityId);

    if (!entity) {
      continue;
    }

    results.push({
      entity,
      depth: current.depth,
      via: current.via,
    });

    if (current.depth >= maxDepth) {
      continue;
    }

    const outgoing = getOutgoing(
      graph,
      current.entityId,
      options.relationshipTypes,
    );

    const incoming = getIncoming(
      graph,
      current.entityId,
      options.relationshipTypes,
    );

    for (const edge of outgoing) {
      if (!visited.has(edge.targetId)) {
        queue.push({
          entityId: edge.targetId,
          depth: current.depth + 1,
          via: edge,
        });
      }
    }

    for (const edge of incoming) {
      if (!visited.has(edge.sourceId)) {
        queue.push({
          entityId: edge.sourceId,
          depth: current.depth + 1,
          via: edge,
        });
      }
    }
  }

  return results;
}

export function findEntitiesByName(
  graph: CodeGraph,
  name: string,
): GraphEntity[] {
  const normalized = name.toLowerCase();

  return Array.from(graph.nodes.values()).filter(
    (entity) =>
      entity.name.toLowerCase() === normalized,
  );
}

export function getGraphStats(graph: CodeGraph) {
  const entityCounts = new Map<string, number>();
  const relationshipCounts = new Map<string, number>();

  for (const entity of graph.nodes.values()) {
    entityCounts.set(
      entity.type,
      (entityCounts.get(entity.type) ?? 0) + 1,
    );
  }

  for (const edge of graph.edges) {
    relationshipCounts.set(
      edge.type,
      (relationshipCounts.get(edge.type) ?? 0) + 1,
    );
  }

  return {
    totalNodes: graph.nodes.size,
    totalEdges: graph.edges.length,
    entityCounts: Object.fromEntries(entityCounts),
    relationshipCounts: Object.fromEntries(
      relationshipCounts,
    ),
  };
}

export function computeRepositoryHash(parsedFiles: ParsedFile[]): string {
  const hash = crypto.createHash("sha256");

  // Sort by filePath for deterministic hash order
  const sorted = [...parsedFiles].sort((a, b) =>
    a.filePath.localeCompare(b.filePath),
  );

  for (const file of sorted) {
    hash.update(file.filePath);
    hash.update(file.content);
  }

  return hash.digest("hex");
}

export async function loadGraphCache(
  cachePath: string = DEFAULT_CACHE_PATH,
): Promise<GraphCacheData | null> {
  try {
    const raw = await fs.readFile(cachePath, "utf-8");
    const data = JSON.parse(raw) as GraphCacheData;

    if (data.version !== CACHE_VERSION) {
      return null;
    }

    return data;
  } catch {
    return null;
  }
}

export async function saveGraphCache(
  data: Omit<GraphCacheData, "version" | "createdAt">,
  cachePath: string = DEFAULT_CACHE_PATH,
): Promise<void> {
  try {
    await fs.mkdir(path.dirname(cachePath), { recursive: true });

    const cachePayload: GraphCacheData = {
      version: CACHE_VERSION,
      repositoryHash: data.repositoryHash,
      createdAt: new Date().toISOString(),
      entities: data.entities,
      relationships: data.relationships,
    };

    await fs.writeFile(
      cachePath,
      JSON.stringify(cachePayload, null, 2),
      "utf-8",
    );
  } catch (error) {
    console.warn("⚠ Failed to save graph cache:", error);
  }
}

function normalizeId(value: string): string {
  return value
    .replace(/\\/g, "/")
    .replace(/[^a-zA-Z0-9/_-]/g, "-")
    .toLowerCase();
}

function createRelationshipId(
  sourceId: string,
  type: RelationshipType,
  targetId: string,
): string {
  return `${sourceId}:${type}:${targetId}`;
}

function createContainsRelationships(
  file: ParsedFile,
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];
  const fileEntityId = `file:${normalizeId(file.filePath)}`;

  const childEntities = entities.filter(
    (entity) =>
      entity.filePath === file.filePath &&
      (entity.type === "function" || entity.type === "class"),
  );

  for (const child of childEntities) {
    relationships.push({
      id: createRelationshipId(fileEntityId, "contains", child.id),
      type: "contains",
      sourceId: fileEntityId,
      targetId: child.id,
      metadata: { filePath: file.filePath },
    });
  }

  return relationships;
}

function resolveImportedFile(file: ParsedFile, source: string, parsedFiles: ParsedFile[]): ParsedFile | undefined {
  if (!source.startsWith(".")) return undefined;
  const joined = path.posix.normalize(path.posix.join(path.posix.dirname(file.filePath), source));
  const base = joined.replace(/\.(?:mjs|cjs|js|jsx|ts|tsx)$/i, "");
  const extensions = ["", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"];
  const candidates = new Set(extensions.flatMap((extension) => [base + extension, `${base}/index${extension}`]));
  return parsedFiles.find((candidate) => candidates.has(candidate.filePath.replace(/\\/g, "/")));
}

function createImportRelationships(file: ParsedFile, parsedFiles: ParsedFile[]): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];
  const fileEntityId = `file:${normalizeId(file.filePath)}`;

  for (const importedModule of file.imports) {
    const resolvedFile = resolveImportedFile(file, importedModule.source, parsedFiles);
    const moduleEntityId = resolvedFile
      ? `file:${normalizeId(resolvedFile.filePath)}`
      : `module:${normalizeId(importedModule.source)}`;

    relationships.push({
      id: createRelationshipId(fileEntityId, "imports", moduleEntityId),
      type: "imports",
      sourceId: fileEntityId,
      targetId: moduleEntityId,
      metadata: {
        source: importedModule.source,
        names: importedModule.names,
        line: importedModule.line,
        resolution: resolvedFile ? "resolved-file" : "external-module",
        ...(resolvedFile ? { resolvedFilePath: resolvedFile.filePath } : {}),
      },
    });
  }

  return relationships;
}

function extractFunctionCalls(functionContent: string): string[] {
  const calls = new Set<string>();

  // Standard function call: foo()
  const callPattern = /\b([A-Za-z_$][A-Za-z0-9_$]*)\s*\(/g;
  // Method call / static class call: Bar.foo() or bar.foo()
  const methodCallPattern = /\b([A-Za-z_$][A-Za-z0-9_$]*)\.([A-Za-z_$][A-Za-z0-9_$]*)\s*\(/g;

  const ignoredCalls = new Set([
    "if",
    "for",
    "while",
    "switch",
    "catch",
    "function",
    "constructor",
    "console",
    "require",
    "super",
    "import",
  ]);

  let match: RegExpExecArray | null;

  while ((match = callPattern.exec(functionContent)) !== null) {
    const functionName = match[1];
    if (functionName && !ignoredCalls.has(functionName)) {
      calls.add(functionName);
    }
  }

  while ((match = methodCallPattern.exec(functionContent)) !== null) {
    const objectName = match[1];
    const methodName = match[2];
    if (objectName && methodName && !ignoredCalls.has(objectName) && !ignoredCalls.has(methodName)) {
      calls.add(`${objectName}.${methodName}`);
      calls.add(methodName);
    }
  }

  return Array.from(calls);
}

function createCallRelationships(
  file: ParsedFile,
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationships: GraphRelationship[] = [];
  const functionEntities = entities.filter((e) => e.type === "function");

  for (const fn of file.functions) {
    const caller = functionEntities.find(
      (e) =>
        e.filePath === file.filePath &&
        e.name === fn.name &&
        e.startLine === fn.startLine,
    );

    if (!caller) {
      continue;
    }

    const calledFunctionNames = extractFunctionCalls(fn.content);

    for (const calledName of calledFunctionNames) {
      if (calledName === fn.name) {
        continue;
      }

      // Priority 1: Same file function resolution
      const sameFileTarget = functionEntities.find(
        (e) => e.filePath === file.filePath && e.name === calledName,
      );

      if (sameFileTarget) {
        relationships.push({
          id: createRelationshipId(caller.id, "calls", sameFileTarget.id),
          type: "calls",
          sourceId: caller.id,
          targetId: sameFileTarget.id,
          metadata: {
            caller: fn.name,
            callee: calledName,
            resolution: "same-file",
          },
        });
        continue;
      }

      // Priority 2: Imported function resolution
      const importedFunctionNames = file.imports.flatMap((imp) => imp.names);
      if (importedFunctionNames.includes(calledName) || calledName.includes(".")) {
        const simpleName = calledName.includes(".") ? calledName.split(".")[1] : calledName;
        const possibleTargets = functionEntities.filter((e) => e.name === calledName || e.name === simpleName);

        if (possibleTargets.length === 1 && possibleTargets[0]) {
          const target = possibleTargets[0];
          relationships.push({
            id: createRelationshipId(caller.id, "calls", target.id),
            type: "calls",
            sourceId: caller.id,
            targetId: target.id,
            metadata: {
              caller: fn.name,
              callee: calledName,
              resolution: "imported-name",
            },
          });
        }
      }
    }
  }

  return relationships;
}

export function extractRelationshipsFromFile(
  file: ParsedFile,
  entities: GraphEntity[],
  parsedFiles: ParsedFile[] = [file],
): GraphRelationship[] {
  return [
    ...createContainsRelationships(file, entities),
    ...createImportRelationships(file, parsedFiles),
    ...createCallRelationships(file, entities),
  ];
}

export function extractRelationships(
  parsedFiles: ParsedFile[],
  entities: GraphEntity[],
): GraphRelationship[] {
  const relationshipMap = new Map<string, GraphRelationship>();

  for (const file of parsedFiles) {
    const relationships = extractRelationshipsFromFile(file, entities, parsedFiles);
    for (const relationship of relationships) {
      if (!relationshipMap.has(relationship.id)) {
        relationshipMap.set(relationship.id, relationship);
      }
    }
  }

  return Array.from(relationshipMap.values());
}

const matchesSource = (citation: string, source: RetrievalResult): boolean => {
  const normCitation = normalize(citation);
  const normSource = normalize(source.source);
  return (
    normCitation === normSource ||
    normCitation === `${normSource} page ${source.page}`
  );
};

export const verifyCitations = ({
  answer,
  sources,
}: CitationCheckRequest): CitationCheckResult => {
  const citations = extractCitations(answer);
  const invalidCitation = citations.find(
    (citation) => !sources.some((source) => matchesSource(citation, source)),
  );

  return citations.length === 0
    ? {
      valid: false,
      citations,
      reason: "No citations were found in the answer.",
    }
    : invalidCitation
      ? {
        valid: false,
        citations,
        reason: `Citation does not match retrieved sources: ${invalidCitation}`,
      }
      : {
        valid: true,
        citations,
        reason: "All citations match retrieved sources.",
      };
};

const isMaliciousInjection = (msg: string): boolean => {
  for (const pattern of INJECTION_PATTERNS) {
    const match = pattern.exec(msg);
    if (!match) continue;

    const matchIndex = match.index;
    const precedingSlice = msg
      .slice(Math.max(0, matchIndex - 80), matchIndex)
      .toLowerCase();

    const isNegated =
      /\b(do\s+not|don'?t|never|must\s+not|should\s+not|avoid|prohibit|prevent|without)\b/i.test(
        precedingSlice,
      );

    const isSecurityEval =
      /\b(evaluat\w+|refuses?|blocks?|security\s+test|classify|deny|allow)\b/i.test(
        precedingSlice,
      ) ||
      (/\b(evaluat\w+|refuses?|blocks?|security\s+test)\b/i.test(msg) &&
        /^\s*[\d\.\-\*]/m.test(
          msg.slice(Math.max(0, matchIndex - 20), matchIndex),
        ));

    if (!isNegated && !isSecurityEval) {
      return true;
    }
  }

  return false;
};

export const validateInput = ({
  message,
}: InputGuardRequest): InputGuardResult => {
  const normalized = message.trim();
  const failure = INPUT_RULES.map((rule) => rule(normalized)).find(Boolean);
  return failure ? { allowed: false, reason: failure } : { allowed: true };
};

export const validateOutput = ({
  response,
}: OutputGuardRequest): OutputGuardResult => {
  const normalized = response.trim();
  const failure = OUTPUT_RULES.map((rule) => rule(normalized)).find(Boolean);
  return failure
    ? { allowed: false, reason: failure }
    : { allowed: true, response: normalized };
};

