      const header = `[${item.id}][${item.sourceType.toUpperCase()}] ${item.source}${
        item.page ? `, page ${item.page}` : item.location ? `, ${item.location}` : ""
      }\n`;
      const itemText = `${header}${item.content}\n\n`;
      const itemTokens = estimateTokens(itemText);

      if (currentTokens + itemTokens <= this.config.maxRagContextTokens) {
        activeEvidence.push(item);
        currentTokens += itemTokens;
      } else {
        // Attempt safe truncation if first item or space allows
        const availableTokens = this.config.maxRagContextTokens - currentTokens;
        if (availableTokens > 100) {
          const maxChars = availableTokens * 4;
          const truncatedContent = item.content.slice(0, maxChars) + "\n...[truncated]";
          const truncatedItem: CompressedEvidence = {
            ...item,
            content: truncatedContent,
          };
          activeEvidence.push(truncatedItem);
          currentTokens += estimateTokens(`${header}${truncatedContent}\n\n`);
        } else {
          droppedChunkCount++;
        }
      }
    }

    droppedChunkCount += Math.max(0, evidence.length - this.config.maxRetrievedChunks);

    const formattedEvidence = activeEvidence
      .map(
        (item) =>
          `[${item.id}][${item.sourceType.toUpperCase()}]\n${item.source}${
            item.page ? `, page ${item.page}` : item.location ? `, ${item.location}` : ""
          }\n${item.content}`,
      )
      .join("\n\n");

    return {
      formattedEvidence,
      evidenceItems: activeEvidence,
      ragContextTokens: currentTokens,
      droppedChunkCount,
    };
  }

  fitMemory(memoryText: string): { formattedMemory: string; memoryTokens: number } {
    const memoryTokens = estimateTokens(memoryText);
    if (memoryTokens <= this.config.maxMemoryTokens) {
      return { formattedMemory: memoryText, memoryTokens };
    }

    const maxChars = this.config.maxMemoryTokens * 4;
    const truncated = memoryText.slice(-maxChars); // keep recent messages
    return {
      formattedMemory: truncated,
      memoryTokens: estimateTokens(truncated),
    };
  }
}

const log = (
  level: LogLevel,
  message: string,
  context: LogContext = {},
): void => {
  const entry = {
    timestamp: new Date().toISOString(),
    level,
    message,
    ...context,
  };

  process.stdout.write(`${JSON.stringify(entry)}\n`);
};

export const requestIdMiddleware: RequestHandler = (
  request,
  response,
  next,
): void => {
  const requestId = request.header("x-request-id")?.trim() || randomUUID();

  response.setHeader("x-request-id", requestId);

  Object.defineProperty(request, "requestId", {
    value: requestId,
    enumerable: false,
    writable: false,
  });

  next();
};

export async function vectorSearch(
  query: string,
  index: VectorDocument[],
  limit = 10,
): Promise<VectorSearchResult[]> {
  const queryEmbedding =
    await embedText(query);

  return index
    .map((document) => ({
      chunk: document.chunk,

      score: cosineSimilarity(
        queryEmbedding,
        document.embedding,
      ),
    }))
    .sort(
      (a, b) =>
        b.score - a.score,
    )
    .slice(0, limit);
}

const hashPassword = (password: string, salt: string): string => {
  return crypto.pbkdf2Sync(password, salt, 1000, 64, "sha512").toString("hex");
};

private seedDefaultUsers(): void {
    const defaultAccounts = [
      { id: "user-admin-1", email: "admin@codegpt.io", name: "Enterprise Admin", tenantId: "tenant-enterprise", role: "admin" as const, password: "password123" },
      { id: "user-alice-1", email: "alice@company-a.com", name: "Alice Developer", tenantId: "tenant-alpha", role: "developer" as const, password: "password123" },
      { id: "user-bob-1", email: "bob@company-b.com", name: "Bob Engineer", tenantId: "tenant-beta", role: "developer" as const, password: "password123" },
    ];

    for (const acc of defaultAccounts) {
      const salt = crypto.randomBytes(16).toString("hex");
      const passwordHash = hashPassword(acc.password, salt);
      const user: User = {
        id: acc.id,
        email: acc.email.toLowerCase(),
        name: acc.name,
        tenantId: acc.tenantId,
        role: acc.role,
        passwordHash,
        salt,
        createdAt: new Date().toISOString(),
      };
      this.usersByEmail.set(user.email, user);
      this.usersById.set(user.id, user);
    }
  }

register(params: {
    email: string;
    name: string;
    password: string;
    tenantId?: string | undefined;
    role?: ("admin" | "developer" | "viewer") | undefined;
  }): User {
    const normalizedEmail = params.email.trim().toLowerCase();
    if (this.usersByEmail.has(normalizedEmail)) {
      throw new AppError("An account with this email already exists", "AUTHENTICATION_ERROR", 409);
    }

    const salt = crypto.randomBytes(16).toString("hex");
    const passwordHash = hashPassword(params.password, salt);
    const userId = "usr-" + crypto.randomUUID().substring(0, 8);
    const tenantId = params.tenantId?.trim() || "t-" + crypto.randomUUID().substring(0, 8);

    const user: User = {
      id: userId,
      email: normalizedEmail,
      name: params.name.trim() || normalizedEmail.split("@")[0] || "User",
      tenantId,
      role: params.role || "developer",
      passwordHash,
      salt,
      createdAt: new Date().toISOString(),
    };

    this.usersByEmail.set(normalizedEmail, user);
    this.usersById.set(userId, user);
    return user;
  }

findByEmail(email: string): User | undefined {
    return this.usersByEmail.get(email.trim().toLowerCase());
  }

findById(id: string): User | undefined {
    return this.usersById.get(id);
  }

verifyPassword(user: User, candidatePassword: string): boolean {
    const candidateHash = hashPassword(candidatePassword, user.salt);
    return crypto.timingSafeEqual(Buffer.from(user.passwordHash), Buffer.from(candidateHash));
  }

export const createSessionToken = (user: User): string => {
  const payload: AuthSession = {
    userId: user.id,
    tenantId: user.tenantId,
    role: user.role,
    email: user.email,
    exp: Date.now() + TOKEN_EXPIRY_MS,
  };

  const encodedPayload = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const signature = crypto.createHmac("sha256", JWT_SECRET).update(encodedPayload).digest("base64url");
  return `${encodedPayload}.${signature}`;
};

getWorkspace(id: string, tenantId?: string): Workspace | undefined {
    const ws = this.workspaces.get(id);
    if (!ws) return undefined;
    if (tenantId && ws.tenantId !== tenantId) return undefined;
    return ws;
  }

updateWorkspace(id: string, tenantId: string, updates: Partial<Pick<Workspace, "name" | "status" | "localPath" | "deviceToken" | "mode">>): Workspace {
    const existing = this.getWorkspace(id, tenantId);
    if (!existing) {
      throw new AppError("Workspace not found", "NOT_FOUND", 404);
    }

    const updated: Workspace = {
      ...existing,
      ...updates,
      updatedAt: new Date().toISOString(),
    };

    this.workspaces.set(id, updated);
    return updated;
  }

