    if (!existing) return false;
    return this.workspaces.delete(id);
  }

export class WorkspaceStore {
  private readonly workspaces = new Map<string, Workspace>();

  constructor() {
    this.seedDefaultWorkspaces();
  }

  private seedDefaultWorkspaces(): void {
    const defaultWs: Workspace = {
      id: "ws-default-cloud",
      tenantId: "tenant-enterprise",
      userId: "user-admin-1",
      name: "Default Cloud Workspace",
      mode: "cloud",
      localPath: process.cwd(),
      status: "active",
      permissions: ["read", "write", "delete", "git", "command", "knowledge"],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    this.workspaces.set(defaultWs.id, defaultWs);
  }

  createWorkspace(params: {
    tenantId: string;
    userId: string;
    name: string;
    mode?: WorkspaceMode | undefined;
    localPath?: string | undefined;
    permissions?: string[] | undefined;
  }): Workspace {
    const name = params.name.trim();
    if (!name) {
      throw new AppError("Workspace name is required", "VALIDATION_ERROR", 400);
    }

    const id = "ws-" + crypto.randomUUID().substring(0, 8);
    const mode = params.mode || "cloud";
    const status: WorkspaceStatus = mode === "local-connector" ? "offline" : "active";

    const workspace: Workspace = {
      id,
      tenantId: params.tenantId,
      userId: params.userId,
      name,
      mode,
      localPath: params.localPath?.trim(),
      status,
      permissions: params.permissions || ["read", "write", "delete", "git", "command", "knowledge"],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    this.workspaces.set(id, workspace);
    return workspace;
  }

  listWorkspaces(tenantId: string, userId?: string): readonly Workspace[] {
    const list: Workspace[] = [];
    for (const ws of this.workspaces.values()) {
      if (ws.tenantId === tenantId) {
        if (!userId || ws.userId === userId || ws.userId === "user-admin-1") {
          list.push(ws);
        }
      }
    }
    return list;
  }

  getWorkspace(id: string, tenantId?: string): Workspace | undefined {
    const ws = this.workspaces.get(id);
    if (!ws) return undefined;
    if (tenantId && ws.tenantId !== tenantId) return undefined;
    return ws;
  }

  updateWorkspace(id: string, tenantId: string, updates: Partial<Pick<Workspace, "name" | "status" | "localPath" | "deviceToken" | "mode">>): Workspace {
    const existing = this.getWorkspace(id, tenantId);
    if (!existing) {
      throw new AppError("Workspace not found", "NOT_FOUND", 404);
    }

    const updated: Workspace = {
      ...existing,
      ...updates,
      updatedAt: new Date().toISOString(),
    };

    this.workspaces.set(id, updated);
    return updated;
  }

  deleteWorkspace(id: string, tenantId: string): boolean {
    const existing = this.getWorkspace(id, tenantId);
    if (!existing) return false;
    return this.workspaces.delete(id);
  }
}

export const createRunTestTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<CommandInput, CommandOutput> => ({
  name: "run_test",
  description: "Executes the test suite in the workspace using a controlled, safe test runner.",
  parameters: {
    type: "object",
    properties: {
      command: {
        type: "string",
        description: "Test command to execute (e.g. 'npm test', 'npx tsc --noEmit', 'pytest')",
      },
    },
    required: [],
  },
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput: (input: unknown) => {
    const raw = (typeof input === "object" && input !== null ? input : {}) as Record<string, unknown>;
    return {
      command: typeof raw.command === "string" ? raw.command.trim() : "npm test",
    };
  },
  execute: async ({ input }) => {
    const cmd = input.command || "npm test";
    if (!SAFE_COMMAND_ALLOWLIST.has(cmd)) {
      throw new Error(
        `Command '${cmd}' is not permitted. Allowed commands: ${[...SAFE_COMMAND_ALLOWLIST].join(", ")}`,
      );
    }

    const startTime = Date.now();
    const [bin, ...args] = cmd.split(/\s+/);
    try {
      const { stdout, stderr } = await execFileAsync(bin!, args, {
        cwd: baseDir,
        timeout: DEFAULT_TIMEOUT_MS,
        maxBuffer: 1024 * 512,
      });

      return {
        command: cmd,
        exitCode: 0,
        stdout: stdout.slice(0, MAX_OUTPUT_CHARS),
        stderr: stderr.slice(0, MAX_OUTPUT_CHARS),
        durationMs: Date.now() - startTime,
      };
    } catch (err: unknown) {
      const execError = err as { code?: number; stdout?: string; stderr?: string; message?: string };
      return {
        command: cmd,
        exitCode: typeof execError.code === "number" ? execError.code : 1,
        stdout: (execError.stdout || "").slice(0, MAX_OUTPUT_CHARS),
        stderr: (execError.stderr || execError.message || "Command failed").slice(0, MAX_OUTPUT_CHARS),
        durationMs: Date.now() - startTime,
      };
    }
  },
});

const extractString = (
  data: Record<string, unknown>,
  keys: readonly string[],
): string => {
  for (const key of keys) {
    if (typeof data[key] === "string" && (data[key] as string).trim().length > 0) {
      return (data[key] as string).trim();
    }
  }
  return "";
};

const parseInput = (input: unknown): DeleteFileInput => {
  const isObject =
    typeof input === "object" && input !== null && !Array.isArray(input);
  !isObject &&
    (() => {
      throw new Error("Invalid delete_file input");
    })();

  const data = input as Record<string, unknown>;
  const rawPath = extractString(data, [
    "path",
    "filePath",
    "file_path",
    "target",
    "folder",
    "directory",
    "filename",
    "file",
  ]);
  !rawPath &&
    (() => {
      throw new Error("File or folder path is required");
    })();

  return { path: rawPath };
};

export const createDeleteFileTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<DeleteFileInput, DeleteFileOutput> => ({
  name: "delete_file",
  description: "Deletes a specified file or directory from the workspace.",
  parameters,
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput,
  execute: async ({ input }) => {
    const targetPath = await resolveWorkspaceCandidate(baseDir, input.path, "delete");

    try {
      const stat = await fs.stat(targetPath);
      if (stat.isDirectory()) {
        await fs.rm(targetPath, { recursive: true, force: true });
        return {
          path: input.path,
          deleted: true,
          message: `Successfully deleted directory '${input.path}'.`,
        };
      }
    } catch {
      // If stat fails, attempt direct unlink
    }

    await fs.unlink(targetPath);

    // Optional: clean parent directory if custom empty dir
    const parentDir = path.dirname(targetPath);
    const parentRel = path.relative(baseDir, parentDir).replace(/\\/g, "/");
    const preservedDirs = new Set(["", "src", "docs", "public", "tests", "migrations", "dist", "node_modules", ".git"]);
    if (!preservedDirs.has(parentRel)) {
      try {
        const entries = await fs.readdir(parentDir);
        if (entries.length === 0) {
          await fs.rm(parentDir, { recursive: true, force: true });
        }
      } catch {
        // Ignore parent cleanup errors
      }
    }

    return {
      path: input.path,
      deleted: true,
      message: `Successfully deleted '${input.path}'.`,
    };
  },
});

