const extractString = (
  data: Record<string, unknown>,
  keys: readonly string[],
): string => {
  for (const key of keys) {
    if (
      typeof data[key] === "string" &&
      (data[key] as string).length > 0
    ) {
      return data[key] as string;
    }
  }
  return "";
};

const parseInput = (input: unknown): EditFileInput => {
  const isObject =
    typeof input === "object" && input !== null && !Array.isArray(input);
  !isObject &&
    (() => {
      throw new Error("Invalid edit_file input");
    })();

  const data = input as Record<string, unknown>;
  const rawPath = extractString(data, [
    "path",
    "filePath",
    "file_path",
    "filename",
    "file",
  ]).trim();
  !rawPath &&
    (() => {
      throw new Error("File path is required");
    })();

  const targetContent = extractString(data, [
    "targetContent",
    "oldContent",
    "old_content",
    "old_text",
    "oldText",
    "target",
    "target_text",
    "search",
    "find",
    "from",
  ]);
  const replacementContent = extractString(data, [
    "replacementContent",
    "new_text",
    "newText",
    "replacement",
    "replacement_text",
    "replace",
    "new_content",
    "newContent",
    "to",
  ]);

  return { path: rawPath, targetContent, replacementContent };
};

export const createEditFileTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<EditFileInput, EditFileOutput> => ({
  name: "edit_file",
  description:
    "Modifies a file in the workspace by replacing targetContent (or old_text) with replacementContent (or new_text).",
  parameters,
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput,
  execute: async ({ input }) => {
    const filePath = await resolveWorkspaceCandidate(baseDir, input.path, "write");
    const existingContent = await fs.readFile(filePath, "utf8");

    const containsTarget = existingContent.includes(input.targetContent);
    !containsTarget &&
      (() => {
        throw new Error(`Target content not found in file '${input.path}'`);
      })();

    const updatedContent = existingContent.replace(
      input.targetContent,
      input.replacementContent,
    );
    await fs.writeFile(filePath, updatedContent, "utf8");

    return {
      path: input.path,
      modified: true,
      message: `Successfully edited '${input.path}'.`,
    };
  },
});

const parseInput = (input: unknown): GitStatusInput => {
  const data = (typeof input === "object" && input !== null ? input : {}) as Record<string, unknown>;
  const rawAction = typeof data.action === "string" ? data.action.toLowerCase().trim() : "status";
  const validAction: GitAction =
    rawAction === "branch" || rawAction === "log" ? rawAction : "status";

  return { action: validAction };
};

export const createGitStatusTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<GitStatusInput, GitStatusOutput> => ({
  name: "git_status",
  description: "Inspects git repository status, active branch, or recent commits in the project workspace.",
  parameters,
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput,
  execute: async ({ input }) => {
    const action: GitAction = input.action ?? "status";
    const args: readonly string[] = ACTION_COMMANDS[action] ?? ACTION_COMMANDS.status;

    try {
      const { stdout } = await execFileAsync("git", [...args], {
        cwd: baseDir,
        timeout: DEFAULT_TIMEOUT_MS,
      });

      return {
        action,
        output: stdout.trim() || "Git repository is clean / working tree clean",
      };
    } catch (error) {
      return {
        action,
        output: `Git command error: ${error instanceof Error ? error.message : String(error)}`,
      };
    }
  },
});

export function analyzeImpact(
  targetName: string,
  graph: CodeGraph,
): ImpactAnalysisReport {
  let targetEntity: GraphEntity | undefined;

  for (const entity of graph.nodes.values()) {
    if (entity.name.toLowerCase() === targetName.toLowerCase()) {
      targetEntity = entity;
      break;
    }
  }

  if (!targetEntity) {
    throw new Error(`Target symbol or file '${targetName}' not found in code graph.`);
  }

  const directDependents: ImpactDependent[] = [];
  const downstreamDependents: ImpactDependent[] = [];
  const visited = new Set<string>([targetEntity.id]);

  const queue: Array<{ id: string; depth: number; via: string }> = [
    { id: targetEntity.id, depth: 0, via: targetEntity.name },
  ];

  let maxDepthFound = 0;
  let directCallersCount = 0;

  while (queue.length > 0) {
    const current = queue.shift()!;
    const incomingEdges = graph.incoming.get(current.id) ?? [];

    for (const incomingEdge of incomingEdges) {
      if (visited.has(incomingEdge.sourceId)) continue;

      visited.add(incomingEdge.sourceId);
      const sourceEntity = graph.nodes.get(incomingEdge.sourceId);

      if (!sourceEntity) continue;

      const depth = current.depth + 1;
      maxDepthFound = Math.max(maxDepthFound, depth);

      const dependentItem: ImpactDependent = {
        entity: sourceEntity,
        relationshipType: incomingEdge.type,
        depth,
        via: current.via,
      };

      if (incomingEdge.type === "calls") {
        if (depth === 1) directCallersCount++;
      }

      if (depth === 1) {
        directDependents.push(dependentItem);
      } else {
        downstreamDependents.push(dependentItem);
      }

      if (depth < 4) {
        queue.push({
          id: sourceEntity.id,
          depth,
          via: sourceEntity.name,
        });
      }
    }
  }

  const totalDependents = directDependents.length + downstreamDependents.length;
  const outgoingCount = (graph.outgoing.get(targetEntity.id) ?? []).length;

  // Calculate Risk Score (0 - 100)
  let riskScore = totalDependents * 15 + directCallersCount * 25 + maxDepthFound * 10;
  if (targetEntity.type === "file") riskScore += 20;

  riskScore = Math.min(100, Math.max(0, riskScore));

  let riskLevel: RiskLevel = "LOW";
  if (riskScore >= 30) riskLevel = "MEDIUM";
  if (riskScore >= 60) riskLevel = "HIGH";
  if (riskScore >= 85) riskLevel = "CRITICAL";

  const explanation = [
    `Impact Analysis for '${targetEntity.name}' (${targetEntity.type}):`,
    `Risk Level: ${riskLevel} (Score: ${riskScore}/100)`,
    `• ${directCallersCount} direct callers / usages`,
    `• ${totalDependents} total downstream dependents across ${maxDepthFound} hop(s)`,
    `• ${outgoingCount} outbound calls/imports`,
  ].join("\n");

  return {
    target: {
      id: targetEntity.id,
      name: targetEntity.name,
      type: targetEntity.type,
      ...(targetEntity.filePath !== undefined && { filePath: targetEntity.filePath }),
    },
    riskLevel,
    riskScore,
    directCallersCount,
    totalDependentsCount: totalDependents,
    maxDependencyDepth: maxDepthFound,
    explanation,
    directDependents,
    downstreamDependents,
  };
}

const sanitizePath = (baseDir: string, requestedPath: string): string => {
  const containsNull = requestedPath.includes("\0");
  containsNull && (() => { throw new Error("Path contains illegal null bytes"); })();

  const resolved = path.resolve(baseDir, requestedPath);
  const relative = path.relative(baseDir, resolved);
  const isEscaping = relative.startsWith("..") || path.isAbsolute(relative);
  isEscaping && (() => { throw new Error("Access denied: path escapes workspace root"); })();

  return resolved;
};

const parseInput = (input: unknown): ListDirectoryInput => {
  const data = (typeof input === "object" && input !== null ? input : {}) as Record<string, unknown>;
  const requestedPath = typeof data.path === "string" && data.path.trim() ? data.path.trim() : ".";
  const recursive = data.recursive === true || String(data.recursive).toLowerCase() === "true";
  const rawMax = typeof data.maxEntries === "number" ? data.maxEntries : Number(data.maxEntries);
  const maxEntries = !isNaN(rawMax) && rawMax > 0 ? Math.min(rawMax, MAX_ALLOWED_ENTRIES) : MAX_ALLOWED_ENTRIES;

  return { path: requestedPath, recursive, maxEntries };
};

