          const data = await res.json();
          if (data.isOnline && data.device) {
            if (modalPairStatusText) {
              modalPairStatusText.textContent = `✅ Connected to ${data.device.deviceName} (${data.device.osPlatform})`;
            }
            showToast(`Workstation connected: ${data.device.deviceName}`, "success");
