const showToast = (message, type = "info") => {
    if (!toastContainer) return;
    const toast = document.createElement("div");
    toast.className = `toast toast-${type}`;
    toast.setAttribute("role", "alert");
    toast.innerHTML = `<span>${escapeHtml(message)}</span>`;
    toastContainer.appendChild(toast);
    requestAnimationFrame(() => toast.classList.add("toast-visible"));
    setTimeout(() => {
      toast.classList.remove("toast-visible");
      setTimeout(() => toast.remove(), 350);
    }, 3500);
  };

const escapeHtml = (text) => {
    if (typeof text !== "string") return "";
    return text
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  };

const formatMarkdown = (text) => {
    if (!text) return "";

    const clean = text
      .replace(/<tool_call>[\s\S]*?<\/tool_call>/gi, "")
      .replace(/<function=[\w]+>[\s\S]*?<\/function>/gi, "")
      .replace(/<parameter=[\w]+>[\s\S]*?<\/parameter>/gi, "")
      .replace(/<\/?(?:function|parameter|tools|tool_call)\b[^>]*>/gi, "")
      .trim();

    let html = escapeHtml(clean);
    const codeBlocks = [];
    const tableBlocks = [];

    html = html.replace(/```([a-zA-Z0-9_-]*)\r?\n([\s\S]*?)\r?\n```/g, (_m, rawLang, code) => {
      const lang = (rawLang || "code").toLowerCase();
      const displayLang =
        lang === "ts" || lang === "typescript" ? "TypeScript" :
          lang === "js" || lang === "javascript" ? "JavaScript" :
            lang === "py" || lang === "python" ? "Python" :
              lang === "sql" ? "SQL" :
                lang === "json" ? "JSON" :
                  lang === "bash" || lang === "sh" ? "Shell" :
                    lang === "html" ? "HTML" :
                      lang === "css" ? "CSS" :
                        lang === "md" || lang === "markdown" ? "Markdown" :
                          rawLang ? rawLang.toUpperCase() : "CODE";
      const idx = codeBlocks.length;
      codeBlocks.push(`
        <div class="code-wrapper">
          <div class="code-header">
            <span class="code-lang-badge"><span class="lang-dot"></span>${displayLang}</span>
            <button class="btn-copy-code" onclick="copyCode(this)" aria-label="Copy code">📋 Copy</button>
          </div>
          <pre><code>${code}</code></pre>
        </div>`);
      return `@@CODE_${idx}@@`;
    });

    html = html.replace(/(^\|.+\|\r?\n^\|(?:\s*:?-+:?\s*\|)+\r?\n(?:^\|.+\|(?:\r?\n|$))+)/gm, (tableText) => {
      const rows = tableText.trim().split(/\r?\n/);
      const parseCells = (row) => row.slice(1, -1).split("|").map((c) => c.trim());
      const headers = parseCells(rows[0]);
      const bodyRows = rows.slice(2).map(parseCells);
      const idx = tableBlocks.length;
      tableBlocks.push(`<div class="md-table-wrap"><table class="md-table"><thead><tr>${headers.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${bodyRows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`);
      return `@@TABLE_${idx}@@`;
    });

    html = html.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    html = html.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    html = html.replace(/`([^`]+)`/g, `<code class="inline-code">$1</code>`);
    html = html.replace(/^### (.*)$/gim, `<h3 class="md-h3">$1</h3>`);
    html = html.replace(/^## (.*)$/gim, `<h2 class="md-h2">$1</h2>`);
    html = html.replace(/^#### (.*)$/gim, `<h4 class="md-h4">$1</h4>`);
    html = html.replace(/\n/g, "<br>");

    for (const [i, b] of codeBlocks.entries()) html = html.replace(`@@CODE_${i}@@`, b);
    for (const [i, t] of tableBlocks.entries()) html = html.replace(`@@TABLE_${i}@@`, t);

    return html;
  };

const buildToolActivityHtml = (toolActivity) => {
    if (!Array.isArray(toolActivity) || toolActivity.length === 0) return "";
    const items = toolActivity.map((t) => `
      <div class="ta-item ${t.success ? "ta-ok" : "ta-fail"}">
        <span class="ta-dot"></span>
        <code class="ta-name">${escapeHtml(t.toolName || "tool")}</code>
        <span class="ta-duration">${t.durationMs ?? 0}ms</span>
        ${t.error
        ? `<span class="ta-status ta-status-err">✕ ${escapeHtml(t.error)}</span>`
        : `<span class="ta-status ta-status-ok">✓ Success</span>`}
      </div>`).join("");
    return `
      <details class="tool-activity-card" open>
        <summary class="ta-header">
          <span class="ta-title">⚡ Autonomous Tool Execution</span>
          <span class="ta-count">${toolActivity.length} step${toolActivity.length === 1 ? "" : "s"}</span>
        </summary>
        <div class="ta-list">${items}</div>
      </details>`;
  };

const buildSourcesHtml = (sources) => {
    if (!Array.isArray(sources) || sources.length === 0) return "";
    const unique = new Map();
    for (const s of sources) {
      const raw = String(s.source || "").replace(/\\/g, "/");
      const repo = raw.match(/(?:^|\/)(?:src|public|tests|docs|migrations)\/.*$/i)?.[0]?.replace(/^\//, "") || raw;
      const label = `${repo}${s.page ? ` (p. ${s.page})` : ""}`;
      if (label && !unique.has(label)) unique.set(label, label);
    }
    const visible = [...unique.values()].slice(0, 5);
    const hidden = unique.size - visible.length;
    const chips = visible.map((l) => `<span class="source-chip">${escapeHtml(l)}</span>`).join("");
    return `<div class="sources-row"><span class="sources-label">Sources</span>${chips}${hidden > 0 ? `<span class="source-chip source-chip-more">+${hidden}</span>` : ""}</div>`;
  };

const appendRow = (role, content, meta = {}) => {
    if (!chatContainer) return;
    if (welcomeCard && !welcomeCard.hidden) welcomeCard.hidden = true;

    const row = document.createElement("div");
    row.className = `chat-row ${role === "user" ? "user-row" : "bot-row"}`;

    const bubbleContent = role === "user"
      ? `<p class="user-text">${escapeHtml(content)}</p>`
      : `
        ${buildToolActivityHtml(meta.toolActivity)}
        <div class="bot-text">${formatMarkdown(content)}</div>
        ${buildSourcesHtml(meta.sources)}
        ${meta.model ? `<div class="model-bar"><span class="model-chip">⚡ ${escapeHtml(meta.model)}</span></div>` : ""}`;

    row.innerHTML = `
      ${role === "assistant" ? `<div class="avatar bot-avatar" aria-hidden="true">🤖</div>` : ""}
      <div class="chat-bubble">${bubbleContent}</div>
      ${role === "user" ? `<div class="avatar user-avatar" aria-hidden="true">👤</div>` : ""}`;

    chatContainer.appendChild(row);
    chatContainer.scrollTop = chatContainer.scrollHeight;
    return row;
  };

const addTypingIndicator = () => {
    const id = `typing-${Date.now()}`;
    const row = document.createElement("div");
    row.id = id;
    row.className = "chat-row bot-row";
    row.innerHTML = `
      <div class="avatar bot-avatar" aria-hidden="true">🤖</div>
      <div class="chat-bubble typing-bubble">
        <span class="typing-dot"></span>
        <span class="typing-dot"></span>
        <span class="typing-dot"></span>
        <span class="typing-label">Executing GraphRAG &amp; autonomous agent tools…</span>
      </div>`;
    chatContainer.appendChild(row);
    chatContainer.scrollTop = chatContainer.scrollHeight;
    return id;
  };

const handleSend = async (overrideText) => {
    const query = typeof overrideText === "string" ? overrideText : userInput?.value.trim();
    if (!query || isSubmitting) return;

    closeSidebarOnMobile();

    if (userInput) {
      userInput.value = "";
      userInput.style.height = "auto";
    }

    appendRow("user", query);
    chatHistory.push({ role: "user", content: query });
    isSubmitting = true;
    if (btnSend) btnSend.disabled = true;

    const typingId = addTypingIndicator();

    try {
      const docIds = [...activeDocumentIds];
      const body = {
        sessionId,
        message: query,
        workspaceId: activeWorkspaceId,
        ...(docIds.length > 0 && { documentIds: docIds }),
      };

      const res = await fetch("/api/chat", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...identityHeaders(),
        },
        body: JSON.stringify(body),
      });

      const data = await res.json();
      document.getElementById(typingId)?.remove();

      if (!res.ok) {
        throw new Error(data.error?.message || `Request failed (${res.status})`);
      }

      if (data.pipeline) {
        const mode = data.pipeline.retrievalMode || "hybrid";
        if (activeRouteLabel) activeRouteLabel.textContent = `M1: ${mode} → M2: agent`;
        if (activeModelBadge) activeModelBadge.textContent = data.model || "GraphRAG Agent";
      }

      const botText = data.message || "Completed.";
      appendRow("assistant", botText, {
        toolActivity: data.toolActivity || [],
        sources: data.sources || [],
        model: data.model,
        pipeline: data.pipeline,
      });
      chatHistory.push({ role: "assistant", content: botText });

      if (Array.isArray(data.toolActivity)) {
        for (const t of data.toolActivity) {
          const pill = document.querySelector(`[data-tool="${t.toolName}"]`);
          if (pill) {
            const dot = pill.querySelector(".tool-pill-dot");
            if (dot) {
              dot.className = `tool-pill-dot ${t.success ? "active" : "error"}`;
              setTimeout(() => (dot.className = "tool-pill-dot ready"), 3500);
            }
          }
        }
      }

    } catch (err) {
      document.getElementById(typingId)?.remove();
      appendRow("assistant", `❌ **Error**: ${err.message}`);
      showToast(err.message, "error");
    } finally {
      isSubmitting = false;
      if (btnSend) btnSend.disabled = false;
      userInput?.focus();
    }
  };

const clearChat = () => {
    chatHistory = [];
    if (chatContainer) chatContainer.innerHTML = "";
    if (welcomeCard) {
      chatContainer.appendChild(welcomeCard);
      welcomeCard.hidden = false;
    }
  };

const startNewChat = () => {
    sessionId = "session-" + Date.now().toString(36);
    updateIdentityDisplay();
    clearChat();
    showToast("Started a new conversation session", "info");
  };

const uploadFile = async (file) => {
    if (!file) return;
    const filename = file.name;
    const mimeType = file.type || "application/octet-stream";

    appendRow("assistant", `⏳ **Indexing Document**: \`${escapeHtml(filename)}\` (${(file.size / 1024).toFixed(1)} KB)…`);

    try {
      const buffer = await file.arrayBuffer();
      const res = await fetch(`/api/documents/upload?filename=${encodeURIComponent(filename)}`, {
        method: "POST",
        headers: {
          "Content-Type": mimeType,
          ...identityHeaders(),
        },
        body: buffer,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error?.message || data.message || "Upload failed");

      const storageLabel = data.document?.storage === "postgres" ? "PostgreSQL/pgvector" : "in-memory fallback";
      appendRow("assistant",
        `✅ **Document Successfully Indexed!**\n- **File**: \`${data.document?.filename}\`\n- **Status**: \`${(data.document?.status || "").toUpperCase()}\`\n- **Vector Chunks**: \`${data.document?.chunks}\` stored in ${storageLabel}\n\nYou can now ask questions about \`${filename}\`!`
      );
      loadDocuments();
      showToast(`${filename} indexed successfully`, "success");
    } catch (err) {
      appendRow("assistant", `❌ **Upload Error**: ${err.message}`);
      showToast(err.message, "error");
    } finally {
      if (fileInput) fileInput.value = "";
    }
  };

const getLogContext = (
  request: Request,
  metadata: Readonly<Record<string, unknown>>,
) => ({
  ...(request.requestId !== undefined && { requestId: request.requestId }),
  operation: request.path,
  metadata,
});

const loadDocuments = async () => {
    if (!uploadedDocsList) return;
    try {
      const res = await fetch("/api/documents", { headers: identityHeaders() });
      const data = await res.json();
      const docs = data.documents || [];
      activeDocumentIds.clear();

      if (docs.length === 0) {
        uploadedDocsList.innerHTML = `<div class="docs-empty-state"><span>No documents indexed yet.</span></div>`;
        return;
      }

      docs.forEach((d) => activeDocumentIds.add(d.id));
      uploadedDocsList.innerHTML = docs.map((d) => `
        <div class="doc-item" data-id="${escapeHtml(d.id)}">
          <span class="doc-name" title="${escapeHtml(d.filename)}">📄 ${escapeHtml(d.filename)}</span>
          <button class="btn-delete-doc" data-id="${escapeHtml(d.id)}" title="Remove document" aria-label="Delete">✕</button>
        </div>`).join("");

      uploadedDocsList.querySelectorAll(".btn-delete-doc").forEach((btn) => {
        btn.addEventListener("click", async (e) => {
          const id = e.currentTarget.getAttribute("data-id");
          if (!id) return;
          try {
            const r = await fetch(`/api/documents/${id}`, {
              method: "DELETE",
              headers: identityHeaders(),
            });
            if (!r.ok) {
              const err = await r.json().catch(() => ({}));
              throw new Error(err.error?.message || "Delete failed");
            }
            loadDocuments();
            showToast("Document removed from vector index", "info");
          } catch (err) {
            showToast(err.message, "error");
          }
        });
      });
    } catch (err) {
      console.warn("[docs] loadDocuments error:", err);
    }
  };

const checkHealth = async () => {
    try {
      const res = await fetch("/health");
      const data = await res.json();
      if (!res.ok) throw new Error(`${res.status}`);

      if (healthDot) healthDot.className = "pulse-indicator";
      if (healthText) {
        const pool = data.database?.poolIdleConnections ?? 0;
        healthText.textContent = `Online • ${data.status.toUpperCase()} (${pool} idle)`;
      }
    } catch {
      if (healthDot) healthDot.className = "pulse-indicator offline";
      if (healthText) healthText.textContent = "Offline • Reconnecting…";
    }
  };

/* ==========================================================================
   CodeGPT Enterprise Design System
   Modern Developer Dark Theme (Linear / Cursor aesthetic)
   ========================================================================== */

/* ── 1. Design Tokens & CSS Custom Properties ───────────────────────────── */
:root {
  /* Color Palette - Core Backgrounds */
  --bg-app: #07090e;
  --bg-sidebar: #0c1017;
  --bg-sidebar-alt: #090c12;
  --bg-card: rgba(16, 22, 34, 0.75);
  --bg-card-hover: rgba(24, 32, 48, 0.85);
  --bg-glass: rgba(255, 255, 255, 0.03);
  --bg-input: rgba(13, 18, 28, 0.85);
  --bg-overlay: rgba(4, 7, 12, 0.75);

  /* Borders */
  --border-subtle: rgba(255, 255, 255, 0.07);
  --border-medium: rgba(255, 255, 255, 0.12);
  --border-focus: rgba(99, 102, 241, 0.6);
  --border-card: rgba(255, 255, 255, 0.08);

  /* Vibrant Accents */
  --accent-indigo: #6366f1;
  --accent-cyan: #06b6d4;
  --accent-emerald: #10b981;
  --accent-amber: #f59e0b;
  --accent-rose: #f43f5e;
  --accent-purple: #8b5cf6;

  /* Typography Colors */
  --text-main: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --text-dimmed: #475569;

  /* Shadows & Glows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.6);
  --shadow-glow: 0 0 24px rgba(99, 102, 241, 0.15);
  --shadow-cyan-glow: 0 0 24px rgba(6, 182, 212, 0.2);

  /* Layout Constants */
  --sidebar-w: 275px;
  --topbar-h: 56px;
  --max-content-w: 920px;
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;

  /* Typography */
  --font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Transitions */
  --ease-fast: 0.15s ease;
  --ease-smooth: 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

/* ── 2. Reset & Global Base ─────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  width: 100%;
  background-color: var(--bg-app);
  color: var(--text-main);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
}

/* Custom Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* ── 3. Ambient Background Lighting ─────────────────────────────────────── */
.ambient-glow {
  position: fixed;
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
  opacity: 0.45;
  filter: blur(100px);
}

.glow-1 {
  top: -150px;
  right: 15%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.12) 0%, transparent 70%);
  animation: floatAmbient 18s ease-in-out infinite alternate;
}

.glow-2 {
