  font-size: 0.72rem;
  color: var(--text-muted);
}

/* Documents List */
.uploaded-docs-list {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  max-height: 140px;
  overflow-y: auto;
}

.docs-empty-state {
  padding: 0.6rem;
  border: 1px dashed var(--border-subtle);
  border-radius: var(--radius-sm);
  text-align: center;
  font-size: 0.72rem;
  color: var(--text-muted);
}

.doc-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.35rem 0.55rem;
  background: var(--bg-glass);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  color: var(--text-secondary);
  transition: all var(--ease-fast);
}

.doc-item:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--border-medium);
  color: var(--text-main);
}

.doc-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 170px;
}

.btn-delete-doc {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0 0.2rem;
  font-size: 0.75rem;
  transition: color var(--ease-fast);
}

.btn-delete-doc:hover {
  color: var(--accent-rose);
}

/* Active Tool Pills */
.tools-count-badge {
  font-size: 0.68rem;
  font-weight: 600;
  padding: 0.1rem 0.4rem;
  border-radius: var(--radius-xs);
  background: rgba(16, 185, 129, 0.12);
  color: var(--accent-emerald);
  border: 1px solid rgba(16, 185, 129, 0.25);
}

.tools-pills-container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.tool-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.5rem;
  background: var(--bg-glass);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xs);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--text-secondary);
  transition: all var(--ease-fast);
}

.tool-pill:hover {
  border-color: var(--border-medium);
  color: var(--text-main);
}

.tool-pill-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--text-dimmed);
}

.tool-pill-dot.ready {
  background: var(--accent-emerald);
}

.tool-pill-dot.active {
  background: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
}

.tool-pill-dot.error {
  background: var(--accent-rose);
}

/* Sidebar Footer & Telemetry */
.sidebar-footer {
  padding: 0.75rem 0.9rem;
  border-top: 1px solid var(--border-subtle);
  flex-shrink: 0;
  background: var(--bg-sidebar-alt);
}

.telemetry-card {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.telemetry-status-row {
  display: flex;
  align-items: center;
  gap: 0.45rem;
}

.pulse-indicator {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-emerald);
  box-shadow: 0 0 8px var(--accent-emerald);
  animation: pulseDot 2.5s infinite;
}

.pulse-indicator.offline {
  background: var(--accent-rose);
  box-shadow: 0 0 8px var(--accent-rose);
}

@keyframes pulseDot {

  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }

  50% {
    transform: scale(1.3);
    opacity: 0.75;
  }
}

.telemetry-status-text {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.telemetry-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.session-tag {
  font-size: 0.68rem;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

/* ── 6. Main Chat Workspace ─────────────────────────────────────────────── */
.chat-workspace {
  flex: 1;
  display: flex;
  flex-direction: column;
  height: 100vh;
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle at 50% 0%, rgba(16, 24, 40, 0.4) 0%, transparent 70%);
}

/* Top Navigation Bar */
.chat-topbar {
  height: var(--topbar-h);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.25rem;
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  background: rgba(7, 9, 14, 0.7);
  flex-shrink: 0;
  z-index: 20;
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.btn-icon-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: var(--bg-glass);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--ease-fast);
}

.btn-icon-toggle:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: var(--border-medium);
  color: var(--text-main);
}

.topbar-pipeline-status {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.status-indicator-badge {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
}

.status-model-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-main);
  letter-spacing: -0.01em;
}

.pipeline-route-path {
  font-size: 0.7rem;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.topbar-quick-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.topbar-chip {
  padding: 0.25rem 0.55rem;
  background: var(--bg-glass);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xs);
  color: var(--text-secondary);
  font-size: 0.72rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--ease-fast);
}

.topbar-chip:hover {
  background: rgba(99, 102, 241, 0.15);
  border-color: rgba(99, 102, 241, 0.4);
  color: var(--text-main);
  transform: translateY(-1px);
}

.btn-topbar-clear {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.65rem;
  background: transparent;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: 0.78rem;
  cursor: pointer;
  transition: all var(--ease-fast);
}

.btn-topbar-clear:hover {
  background: rgba(244, 63, 94, 0.1);
  border-color: rgba(244, 63, 94, 0.3);
  color: var(--accent-rose);
}

/* ── 7. Messages Scroll Area ────────────────────────────────────────────── */
.messages-container {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem 1.25rem 7rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  max-width: var(--max-content-w);
  width: 100%;
  margin: 0 auto;
}

/* Welcome Hero Experience */
.welcome-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 2.5rem 1rem 1rem;
  margin: auto 0;
  gap: 1.25rem;
  animation: fadeIn 0.4s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.25rem 0.75rem;
  background: rgba(99, 102, 241, 0.12);
  border: 1px solid rgba(99, 102, 241, 0.25);
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-indigo);
  letter-spacing: 0.02em;
}

.sparkle {
  color: var(--accent-cyan);
}

.hero-headline {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.2;
  color: var(--text-main);
  max-width: 650px;
}

.gradient-text {
  background: linear-gradient(135deg, #6366f1 0%, #06b6d4 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-subline {
  font-size: 0.95rem;
  color: var(--text-secondary);
  max-width: 580px;
  line-height: 1.6;
}

/* Interactive Hero Prompt Cards Grid */
.hero-prompts-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
  width: 100%;
  max-width: 680px;
  margin-top: 0.5rem;
}

.hero-prompt-card {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.85rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  cursor: pointer;
  text-align: left;
  transition: all var(--ease-smooth);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
}

.hero-prompt-card:hover {
  background: var(--bg-card-hover);
  border-color: rgba(99, 102, 241, 0.35);
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
}

.prompt-icon-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.prompt-icon-box.cyan {
  background: rgba(6, 182, 212, 0.12);
  color: var(--accent-cyan);
}

.prompt-icon-box.amber {
  background: rgba(245, 158, 11, 0.12);
  color: var(--accent-amber);
}

.prompt-icon-box.indigo {
  background: rgba(99, 102, 241, 0.12);
  color: var(--accent-indigo);
}

.prompt-icon-box.emerald {
  background: rgba(16, 185, 129, 0.12);
  color: var(--accent-emerald);
}

.prompt-text-group {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1;
  min-width: 0;
}

.prompt-title {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-main);
}

.prompt-desc {
  font-size: 0.72rem;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.prompt-arrow {
  color: var(--text-dimmed);
  font-size: 0.95rem;
  transition: transform var(--ease-fast);
}

.hero-prompt-card:hover .prompt-arrow {
  transform: translateX(3px);
  color: var(--text-main);
}

.hero-capabilities-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  margin-top: 0.5rem;
}

.capability-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.72rem;
  color: var(--text-muted);
  padding: 0.2rem 0.55rem;
  background: var(--bg-glass);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xs);
}

.capability-tag .dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-indigo);
}

/* ── 8. Chat Message Rows & Bubbles ─────────────────────────────────────── */
.chat-row {
  display: flex;
  gap: 0.75rem;
  width: 100%;
  animation: fadeIn 0.2s ease-out;
}

.user-row {
  justify-content: flex-end;
}

.bot-row {
  justify-content: flex-start;
}

.avatar {
  width: 30px;
  height: 30px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
  flex-shrink: 0;
}

.user-avatar {
  background: rgba(99, 102, 241, 0.2);
  border: 1px solid rgba(99, 102, 241, 0.4);
}

.bot-avatar {
  background: rgba(6, 182, 212, 0.15);
  border: 1px solid rgba(6, 182, 212, 0.35);
}

.chat-bubble {
  max-width: 85%;
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md);
  font-size: 0.88rem;
  line-height: 1.6;
}

.user-row .chat-bubble {
  background: var(--accent-indigo);
  color: #ffffff;
  border-bottom-right-radius: var(--radius-xs);
}

.bot-row .chat-bubble {
  background: var(--bg-card);
  border: 1px solid var(--border-medium);
  color: var(--text-main);
  border-bottom-left-radius: var(--radius-xs);
  box-shadow: var(--shadow-sm);
}

.user-text {
  word-break: break-word;
  white-space: pre-wrap;
}

/* Markdown Content Elements */
.bot-text {
  word-break: break-word;
}

.bot-text .md-h2 {
  font-size: 1.15rem;
  font-weight: 700;
  margin: 0.8rem 0 0.4rem;
  color: var(--text-main);
}

.bot-text .md-h3 {
  font-size: 1rem;
  font-weight: 600;
  margin: 0.6rem 0 0.3rem;
  color: var(--text-main);
}

.bot-text .md-h4 {
  font-size: 0.9rem;
  font-weight: 600;
  margin: 0.5rem 0 0.25rem;
  color: var(--text-secondary);
}

.inline-code {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  padding: 0.12rem 0.35rem;
  border-radius: var(--radius-xs);
  background: rgba(255, 255, 255, 0.08);
  color: var(--accent-cyan);
  border: 1px solid var(--border-subtle);
}

/* Code Snippet Wrapper */
.code-wrapper {
  margin: 0.75rem 0;
  border-radius: var(--radius-md);
  background: #06080d;
  border: 1px solid var(--border-medium);
  overflow: hidden;
}

.code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.4rem 0.8rem;
  background: rgba(255, 255, 255, 0.03);
  border-bottom: 1px solid var(--border-subtle);
}

.code-lang-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
}

.lang-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan);
}

.btn-copy-code {
  background: transparent;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xs);
  color: var(--text-muted);
  font-size: 0.72rem;
  padding: 0.15rem 0.45rem;
  cursor: pointer;
  transition: all var(--ease-fast);
}

.btn-copy-code:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-main);
  border-color: var(--border-medium);
}

.code-wrapper pre {
  padding: 0.85rem 1rem;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.55;
  color: #e2e8f0;
}

/* Markdown Tables */
.md-table-wrap {
  margin: 0.75rem 0;
  overflow-x: auto;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
}

.md-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

.md-table th,
.md-table td {
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border-subtle);
  text-align: left;
}

.md-table th {
  background: rgba(255, 255, 255, 0.04);
  font-weight: 600;
  color: var(--text-secondary);
}

.md-table tr:hover td {
  background: rgba(255, 255, 255, 0.02);
}

/* Tool Activity Card */
.tool-activity-card {
  margin-bottom: 0.65rem;
  border-radius: var(--radius-sm);
  background: rgba(6, 182, 212, 0.04);
  border: 1px solid rgba(6, 182, 212, 0.2);
  overflow: hidden;
}

.ta-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.45rem 0.75rem;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-cyan);
}

.ta-count {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  padding: 0.1rem 0.35rem;
  border-radius: var(--radius-xs);
  background: rgba(6, 182, 212, 0.15);
}

.ta-list {
  padding: 0.35rem 0.75rem 0.55rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  border-top: 1px solid rgba(6, 182, 212, 0.12);
}

.ta-item {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.72rem;
}

.ta-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.ta-ok .ta-dot {
  background: var(--accent-emerald);
}

.ta-fail .ta-dot {
  background: var(--accent-rose);
}

.ta-name {
  font-family: var(--font-mono);
  color: var(--text-main);
}

.ta-duration {
  font-family: var(--font-mono);
  color: var(--text-dimmed);
}

.ta-status {
  margin-left: auto;
  font-size: 0.68rem;
}

.ta-status-ok {
  color: var(--accent-emerald);
}

.ta-status-err {
  color: var(--accent-rose);
}

/* Citations & Sources Row */
.sources-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.65rem;
  padding-top: 0.55rem;
  border-top: 1px solid var(--border-subtle);
}

.sources-label {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  margin-right: 0.2rem;
}

.source-chip {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-xs);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.source-chip-more {
  background: rgba(99, 102, 241, 0.12);
  color: var(--accent-indigo);
}

.model-bar {
  margin-top: 0.45rem;
}

.model-chip {
  font-size: 0.68rem;
  color: var(--text-dimmed);
  font-family: var(--font-mono);
}

/* Typing Indicator */
.typing-bubble {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.typing-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-cyan);
  animation: typingBounce 1.4s infinite ease-in-out both;
}

.typing-dot:nth-child(1) {
  animation-delay: -0.32s;
}

.typing-dot:nth-child(2) {
  animation-delay: -0.16s;
}

@keyframes typingBounce {

  0%,
  80%,
  100% {
    transform: scale(0);
    opacity: 0.3;
  }

  40% {
    transform: scale(1);
    opacity: 1;
  }
}

.typing-label {
  margin-left: 0.4rem;
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ── 9. Bottom Floating Input ───────────────────────────────────────────── */
.input-container-floating {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1rem 1.25rem 1.25rem;
  background: linear-gradient(to top, #07090e 70%, transparent 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  z-index: 30;
}

.input-panel-glass {
  max-width: var(--max-content-w);
  width: 100%;
  background: var(--bg-input);
  border: 1px solid var(--border-medium);
  border-radius: var(--radius-lg);
  padding: 0.45rem 0.65rem 0.45rem 0.85rem;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  box-shadow: var(--shadow-lg), var(--shadow-glow);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  transition: border-color var(--ease-fast);
}

.input-panel-glass:focus-within {
  border-color: var(--border-focus);
}

.btn-attach-action {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.45rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--ease-fast);
}

.btn-attach-action:hover {
  color: var(--text-main);
  background: rgba(255, 255, 255, 0.06);
}

#user-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text-main);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  line-height: 1.45;
  resize: none;
  outline: none;
  max-height: 180px;
  padding: 0.45rem 0;
}

#user-input::placeholder {
  color: var(--text-muted);
}

.btn-send-action {
  background: var(--accent-indigo);
