          ? file.content.split("\n").find((line) => line.includes(nextName))?.trim()
          : undefined;
        return `${index + 1}. \`${file.path}\`${reference ? ` references the next component through \`${reference}\`` : " participates in the execution path"} [${file.path}].`;
      });
      return {
