      localPath: typeof localPath === "string" ? localPath : undefined,
      permissions: Array.isArray(permissions) ? permissions : undefined,
    });

    response.status(201).json({ workspace });
  } catch (error) {
    next(error);
  }
}

export async function getWorkspaceHandler(
