const evaluateCase = (
  evaluationCase: EvaluationCase,
  result: AgentExecutionResult,
): EvaluationResult => {
  const actualRetrieval = result.sources.length > 0;
  const actualSources = result.sources.map(({ source }) => source);
  const actualCitations = extractCitations(result.text);

  const responseMatches =
    result.responseId === evaluationCase.expectedResponseId;
  const retrievalMatches = actualRetrieval === evaluationCase.expectRetrieval;
  const sourceMatches =
    evaluationCase.expectedSource === undefined ||
    actualSources.includes(evaluationCase.expectedSource);

  return {
    caseId: evaluationCase.id,
    passed: responseMatches && retrievalMatches && sourceMatches,
    expectedResponseId: evaluationCase.expectedResponseId,
    actualResponseId: result.responseId,
    expectedRetrieval: evaluationCase.expectRetrieval,
    actualRetrieval,
    ...(evaluationCase.expectedSource !== undefined && {
      expectedSource: evaluationCase.expectedSource,
    }),
    actualSources,
    ...(evaluationCase.expectedCitations !== undefined && {
      expectedCitations: evaluationCase.expectedCitations,
    }),
    ...(actualCitations.length > 0 && { actualCitations }),
  };
};

export const evaluateDataset = async (
  cases: readonly EvaluationCase[],
  run: (evaluationCase: EvaluationCase) => Promise<AgentExecutionResult>,
): Promise<EvaluationReport> => {
  const results = await Promise.all(
    cases.map(async (evaluationCase) =>
      evaluateCase(evaluationCase, await run(evaluationCase)),
    ),
  );

  const observations: EvaluationObservation[] = results.map(
    ({
      passed,
      expectedRetrieval,
      actualRetrieval,
      expectedCitations,
      actualCitations,
    }) => ({
      passed,
      expectedRetrieval,
      actualRetrieval,
      ...(expectedCitations !== undefined && { expectedCitations }),
      ...(actualCitations !== undefined && { actualCitations }),
    }),
  );

  return {
    results,
    metrics: calculateMetrics(observations),
  };
};

export const calculateMetrics = (
  observations: readonly EvaluationObservation[],
): EvaluationMetrics => {
  const total = observations.length;
  const passed = observations.filter((item) => item.passed).length;
  const failed = total - passed;
  const retrievalChecks = observations.filter(
    (item) => item.expectedRetrieval === item.actualRetrieval,
  ).length;

  const validObservations = observations.filter(
    (
      obs,
    ): obs is EvaluationObservation & {
      expectedCitations: readonly string[];
      actualCitations: readonly string[];
    } => Boolean(obs.expectedCitations && obs.actualCitations),
  );

  const citationStats = validObservations.map((obs) => {
    const expectedSet = new Set(obs.expectedCitations);
    const actualSet = new Set(obs.actualCitations);
    const truePositives = [...actualSet].filter((c) =>
      expectedSet.has(c),
    ).length;
    const precision = actualSet.size === 0 ? 1 : truePositives / actualSet.size;
    const recall =
      expectedSet.size === 0 ? 1 : truePositives / expectedSet.size;
    return { precision, recall };
  });

  const citationCount = citationStats.length;
  const totalPrecision = citationStats.reduce(
    (acc, s) => acc + s.precision,
    0,
  );
  const totalRecall = citationStats.reduce((acc, s) => acc + s.recall, 0);

  const citationPrecision =
    citationCount === 0 ? 0 : totalPrecision / citationCount;
  const citationRecall =
    citationCount === 0 ? 0 : totalRecall / citationCount;
  const citationSum = citationPrecision + citationRecall;
  const citationF1 =
    citationSum === 0
      ? 0
      : (2 * citationPrecision * citationRecall) / citationSum;

  return {
    total,
    passed,
    failed,
    passRate: total === 0 ? 0 : passed / total,
    retrievalAccuracy: total === 0 ? 0 : retrievalChecks / total,
    citationPrecision,
    citationRecall,
    citationF1,
  };
};

function normalizeId(value: string): string {
  return value
    .replace(/\\/g, "/")
    .replace(/[^a-zA-Z0-9/_-]/g, "-")
    .toLowerCase();
}

function createFileEntity(file: ParsedFile): GraphEntity {
  return {
    id: `file:${normalizeId(file.filePath)}`,

    type: "file",

    name: path.basename(file.filePath),

    filePath: file.filePath,

    startLine: 1,

    endLine: file.content
      ? file.content.split(/\r?\n/).length
      : 1,

    language: file.language,

    metadata: {
      directory: path.dirname(file.filePath),
      imports: file.imports.map((item) => item.source),
    },
  };
}

function createFunctionEntity(
  file: ParsedFile,
  fn: ParsedFunction,
): GraphEntity {
  return {
    id: `function:${normalizeId(file.filePath)}:${normalizeId(fn.name)}:${fn.startLine}`,

    type: "function",

    name: fn.name,

    filePath: file.filePath,

    startLine: fn.startLine,
    endLine: fn.endLine,

    language: file.language,

    metadata: {
      parentFile: file.filePath,
    },
  };
}

function createClassEntity(
  file: ParsedFile,
  classInfo: ParsedClass,
): GraphEntity {
  return {
    id: `class:${normalizeId(file.filePath)}:${normalizeId(classInfo.name)}:${classInfo.startLine}`,

    type: "class",

    name: classInfo.name,

    filePath: file.filePath,

    startLine: classInfo.startLine,
    endLine: classInfo.endLine,

    language: file.language,

    metadata: {
      parentFile: file.filePath,
    },
  };
}

function createModuleEntities(
  file: ParsedFile,
): GraphEntity[] {
  const modules: GraphEntity[] = [];

  for (const importedModule of file.imports) {
    modules.push({
      id: `module:${normalizeId(importedModule.source)}`,

      type: "module",

      name: importedModule.source,

      metadata: {
        importedBy: file.filePath,
      },
    });
  }

  return modules;
}

export function parseTypeScriptAST(
  content: string,
  filePath: string,
): ASTParseResult {
  const scriptTarget = ts.ScriptTarget.Latest;
  const sourceFile = ts.createSourceFile(
    filePath,
    content,
    scriptTarget,
    true, // setParentNodes
  );

  const imports: ParsedImport[] = [];
  const functions: ParsedFunction[] = [];
  const classes: ParsedClass[] = [];

  function getLineNumber(pos: number): number {
    return sourceFile.getLineAndCharacterOfPosition(pos).line + 1;
  }

  function getNodeContent(node: ts.Node): string {
    return node.getText(sourceFile);
  }

  function visit(node: ts.Node) {
    // 1. Imports
    if (ts.isImportDeclaration(node)) {
      const moduleSpecifier = (node.moduleSpecifier as ts.StringLiteral).text;
      const names: string[] = [];

      if (node.importClause) {
        if (node.importClause.name) {
          names.push(node.importClause.name.getText(sourceFile));
        }

        if (node.importClause.namedBindings) {
          if (ts.isNamedImports(node.importClause.namedBindings)) {
            for (const element of node.importClause.namedBindings.elements) {
              names.push(element.name.getText(sourceFile));
            }
          } else if (ts.isNamespaceImport(node.importClause.namedBindings)) {
            names.push(node.importClause.namedBindings.name.getText(sourceFile));
          }
        }
      }

      imports.push({
        source: moduleSpecifier,
        names,
        line: getLineNumber(node.getStart()),
      });
    }

    // 2. Function Declarations
    else if (ts.isFunctionDeclaration(node) && node.name) {
      const name = node.name.getText(sourceFile);
      const startLine = getLineNumber(node.getStart());
      const endLine = getLineNumber(node.getEnd());

      functions.push({
        name,
        startLine,
        endLine,
        content: getNodeContent(node),
      });
    }

    // 3. Arrow Function / Function Expression Variable Declarations
    else if (ts.isVariableDeclaration(node) && node.name && node.initializer) {
      if (
        ts.isArrowFunction(node.initializer) ||
        ts.isFunctionExpression(node.initializer)
      ) {
        const name = node.name.getText(sourceFile);
        const startLine = getLineNumber(node.getStart());
        const endLine = getLineNumber(node.getEnd());

        functions.push({
          name,
          startLine,
          endLine,
          content: getNodeContent(node.parent?.parent ?? node),
        });
      }
    }

    // 4. Class Declarations & Methods
    else if (ts.isClassDeclaration(node) && node.name) {
      const className = node.name.getText(sourceFile);
      const classStartLine = getLineNumber(node.getStart());
      const classEndLine = getLineNumber(node.getEnd());

      classes.push({
        name: className,
        startLine: classStartLine,
        endLine: classEndLine,
        content: getNodeContent(node),
      });

      // Extract class methods as functions
      for (const member of node.members) {
        if (ts.isMethodDeclaration(member) && member.name) {
          const methodName = member.name.getText(sourceFile);
          const methodStartLine = getLineNumber(member.getStart());
          const methodEndLine = getLineNumber(member.getEnd());

          functions.push({
            name: `${className}.${methodName}`,
            startLine: methodStartLine,
            endLine: methodEndLine,
            content: getNodeContent(member),
          });
        }
      }
    }

    ts.forEachChild(node, visit);
  }

  visit(sourceFile);

  return {
    imports,
    functions,
    classes,
  };
}

