const sanitizeWorkspaceRoot = (raw: string | undefined): string => {
  const fallback = process.cwd();
  if (!raw?.trim()) return fallback;

  const candidate = raw.trim();

  // Reject paths containing null bytes or traversal sequences
  if (candidate.includes("\0") || candidate.includes("..")) {
    return fallback;
  }

  // Must be an absolute path
  if (!path.isAbsolute(candidate)) {
    return fallback;
  }

  // Normalize separators (tolerate forward slashes on Windows)
  const normalized = path.normalize(candidate);

  // If an allowlist is configured, enforce it
  if (WORKSPACE_ALLOWLIST.length > 0) {
    const allowed = WORKSPACE_ALLOWLIST.some((prefix) =>
      normalized.startsWith(path.normalize(prefix))
    );
    if (!allowed) return fallback;
  }

  return normalized;
};

export const createSecurityMiddleware = (requiredPermission?: Permission) => {
  return (request: Request, response: Response, next: NextFunction): void => {
    try {
      let tenantId = request.header("x-tenant-id")?.trim();
      let userId = request.header("x-user-id")?.trim();
      let role = request.header("x-user-role")?.trim() ?? "user";

      // 1. Check for Bearer token authorization
      const authHeader = request.header("authorization")?.trim();
      if (authHeader && authHeader.startsWith("Bearer ")) {
        const token = authHeader.slice(7).trim();
        try {
          const session = verifySessionToken(token);
          tenantId = session.tenantId;
          userId = session.userId;
          role = session.role;
        } catch (authErr) {
          response.status(401).json({
            error: {
              code: "AUTHENTICATION_ERROR",
              message: authErr instanceof Error ? authErr.message : "Invalid authentication token",
            },
          });
          return;
        }
      }

      if (!tenantId || !userId) {
        response.status(401).json({
          error: {
            code: "AUTHENTICATION_ERROR",
            message: "Tenant and user identity are required.",
          },
        });
        return;
      }

      const validTenantId: string = tenantId;
      const validUserId: string = userId;
      const context = createTenantContext(validTenantId, validUserId);

      const reqPath = request.path ?? "";
      const reqMethod = request.method ?? "POST";

      const permissionToCheck: Permission =
        requiredPermission ??
        (reqPath.includes("/documents")
          ? reqMethod === "GET"
            ? "documents:read"
            : "documents:write"
          : "chat:write");

      const unauthorized = !authorize({
        context,
        role,
        permission: permissionToCheck,
      });

      if (unauthorized) {
        response.status(403).json({
          error: {
            code: "AUTHORIZATION_ERROR",
            message: "You are not authorized to perform this operation.",
          },
        });
        return;
      }

      const rateLimit = rateLimiter.check(context.tenantId);
      if (!rateLimit.allowed) {
        response.status(429).json({
          error: {
            code: "RATE_LIMITED",
            message: "Too many requests.",
          },
          retryAt: rateLimit.resetAt,
        });
        return;
      }

      // Attach tenant context
      request.tenantContext = context;

      // Attach workspace root (sanitized — never trust raw header value)
      request.workspaceRoot = sanitizeWorkspaceRoot(
        request.header("x-workspace-root")
      );

      // Attach workspace ID
      const wsHeader = request.header("x-workspace-id")?.trim();
      if (wsHeader) {
        request.workspaceId = wsHeader;
      }

      next();
    } catch (error) {
      next(error);
    }
  };
};

public recordRetrieval(
    totalMs: number,
    vectorMs: number,
    graphMs: number,
    rerankMs: number,
    success = true,
    queryText = "",
    repository = "ai-chatbot",
  ): void {
    this.retrievalRequests++;
    if (!success) {
      this.failedRetrievals++;
    }

    this.totalRetrievalLatencyMs += totalMs;
    this.totalVectorLatencyMs += vectorMs;
    this.totalGraphLatencyMs += graphMs;
    this.totalRerankLatencyMs += rerankMs;

    this.latencySamples.push(totalMs);
    if (this.latencySamples.length > 1000) {
      this.latencySamples.shift();
    }

    // Record per-repository metrics
    const repoStats = this.repoMetricsMap.get(repository) ?? {
      total: 0,
      failed: 0,
      totalLatencyMs: 0,
    };
    repoStats.total++;
    if (!success) repoStats.failed++;
    repoStats.totalLatencyMs += totalMs;
    this.repoMetricsMap.set(repository, repoStats);

    // Record slow query log if latency exceeds threshold
    if (totalMs >= this.SLOW_QUERY_THRESHOLD_MS && queryText) {
      this.slowQueries.push({
        timestamp: new Date().toISOString(),
        query: queryText,
        repository,
        totalMs,
        vectorMs,
        graphMs,
        rerankMs,
      });

      if (this.slowQueries.length > 50) {
        this.slowQueries.shift(); // Keep latest 50 slow queries
      }
    }
  }

public recordDbQuery(success = true): void {
    this.dbQueries++;
    if (!success) {
      this.failedDbQueries++;
    }
  }

public recordCacheHit(hit: boolean): void {
    if (hit) {
      this.cacheHits++;
    } else {
      this.cacheMisses++;
    }
  }

