function scoreEntity(
  entity: GraphEntity,
  query: string,
  terms: string[],
): {
  score: number;
  matchType?: GraphSearchResult["matchType"] | undefined;
  matchedTerm?: string | undefined;
} {
  const normalizedQuery =
    normalizeText(query);

  const normalizedName =
    normalizeText(entity.name);

  const searchableText =
    getEntitySearchText(entity);

  /*
   * Exact entity name match.
   *
   * Example:
   * query = "normalizeId"
   * entity = normalizeId
   */
  if (
    normalizedName === normalizedQuery
  ) {
    return {
      score: 1,
      matchType: "exact",
      matchedTerm: query,
    };
  }

  /*
   * Query contains entire entity name.
   *
   * Example:
   * "where is normalizeId used"
   */
  if (
    normalizedName.length > 1 &&
    normalizedQuery.includes(
      normalizedName,
    )
  ) {
    return {
      score: 0.9,
      matchType: "name",
      matchedTerm: entity.name,
    };
  }

  let matchedTerms = 0;
  let strongestTerm: string | undefined;

  for (const term of terms) {
    if (searchableText.includes(term)) {
      matchedTerms++;

      if (
        !strongestTerm ||
        term.length > strongestTerm.length
      ) {
        strongestTerm = term;
      }
    }
  }

  if (matchedTerms === 0) {
    return {
      score: 0,
    };
  }

  const coverage =
    matchedTerms /
    Math.max(terms.length, 1);

  /*
   * Keep lexical seed results below
   * exact/name matches.
   */
  const score =
    0.45 +
    coverage * 0.35;

  return {
    score,
    matchType: "partial",
    matchedTerm: strongestTerm,
  };
}

