function findFirstRelevantRank(
  returned: string[],
  expected: string[],
): number | null {
  for (
    let index = 0;
    index < returned.length;
    index++
  ) {
    const item = returned[index];
    if (
      item !== undefined &&
      expected.includes(
        item,
      )
    ) {
      return index + 1;
    }
  }

  return null;
}

function calculateRecallAtK(
  returned: string[],
  expected: string[],
  k: number,
): number {
  const topK =
    returned.slice(0, k);

  const relevantFound =
    expected.filter(
      (name) =>
        topK.includes(name),
    );

  return (
    relevantFound.length /
    expected.length
  );
}

