export function explainRetrievedContext(
  context: RetrievedContext,
  query: string,
): ExplainableRetrievedContext {
  const reasons: string[] = [];

  if (context.sources.includes("vector") && context.sources.includes("graph")) {
    reasons.push("Hybrid agreement: High similarity vector embedding + AST Graph structural match");
  } else if (context.sources.includes("vector")) {
    reasons.push("Semantic similarity vector embedding match");
  } else if (context.sources.includes("graph")) {
    reasons.push("AST Graph traversal neighbor match");
  }

  if (context.rerankScore && context.rerankScore > 0.5) {
    reasons.push("Deterministic code signal bonus (identifier token overlap & type bonus)");
  }

  if (context.name.toLowerCase().includes(query.toLowerCase())) {
    reasons.push(`Exact identifier substring match for query token '${query}'`);
  }

  const matchSummary = `Rank #${context.rank}: ${context.name} (${context.type ?? "chunk"}) — Score: ${context.score.toFixed(4)}`;
  const structuralImportance = `Vector Score: ${context.vectorScore.toFixed(4)} | Graph Score: ${context.graphScore.toFixed(4)}`;

  return {
    ...context,
    explanation: {
      matchSummary,
      structuralImportance,
      relevanceReasons: reasons,
    },
  };
}

function normalizeText(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9_$]+/g, " ")
    .trim();
}

function tokenizeQuery(
  query: string,
): string[] {
  const stopWords = new Set([
    "the",
    "a",
    "an",
    "is",
    "are",
    "where",
    "what",
    "which",
    "how",
    "does",
    "do",
    "in",
    "of",
    "to",
    "for",
    "and",
    "or",
    "used",
    "use",
  ]);

  const baseTokens = normalizeText(query)
    .split(/\s+/)
    .filter(Boolean)
    .filter(
      (token) =>
        token.length > 1 &&
        !stopWords.has(token),
    );

  const expanded = new Set(baseTokens);

  for (const token of baseTokens) {
    for (
      const expansion
      of QUERY_EXPANSIONS[token] ?? []
    ) {
      expanded.add(expansion);
    }
  }

  return Array.from(expanded);
}

function getEntitySearchText(
  entity: GraphEntity,
): string {
  return normalizeText(
    [
      entity.name,
      entity.filePath ?? "",
      entity.type,
    ].join(" "),
  );
}

function findSeedEntities(
  graph: CodeGraph,
  query: string,
  options: GraphSearchOptions,
): GraphSearchResult[] {
  const terms = tokenizeQuery(query);

  const results: GraphSearchResult[] = [];

  for (const entity of graph.nodes.values()) {
    if (
      options.entityTypes &&
      options.entityTypes.length > 0 &&
      !options.entityTypes.includes(
        entity.type,
      )
    ) {
      continue;
    }

    const scored =
      scoreEntity(
        entity,
        query,
        terms,
      );

    if (
      scored.score <= 0 ||
      !scored.matchType
    ) {
      continue;
    }

    results.push({
      entity,

      score: scored.score,

      matchType: scored.matchType,

      depth: 0,

      matchedTerm:
        scored.matchedTerm,
    });
  }

  return results.sort(
    (a, b) => b.score - a.score,
  );
}

function scoreGraphExpansion(
  traversal: TraversalResult,
  seedScore: number,
): number {
  /*
   * Graph-connected results lose some
   * relevance at every hop.
   *
   * depth 1: ~75% of seed score
   * depth 2: ~50%
   * depth 3: ~25%
   */
  const decay =
    Math.max(
      0.25,
      1 - traversal.depth * 0.25,
    );

  return seedScore * decay;
}

export function graphSearch(
  graph: CodeGraph,
  query: string,
  options: GraphSearchOptions = {},
): GraphSearchResult[] {
  const limit = options.limit ?? 10;
  const maxDepth = validateGraphDepth(options.maxDepth);

  const seeds = findSeedEntities(graph, query, options);

  if (seeds.length === 0) {
    return [];
  }

  const seedLimit = Math.min(seeds.length, 5);
  const selectedSeeds = seeds.slice(0, seedLimit);
  const resultMap = new Map<string, GraphSearchResult>();

  let totalNodesVisited = 0;

  for (const seed of selectedSeeds) {
    resultMap.set(seed.entity.id, seed);

    const traversal = traverseGraph(graph, seed.entity.id, {
      maxDepth,
      relationshipTypes: options.relationshipTypes,
    });

    for (const traversed of traversal) {
      totalNodesVisited++;
      if (totalNodesVisited > LIMITS.maxGraphNodesVisited) {
        console.warn(`⚠️ Bounded graph traversal at node limit (${LIMITS.maxGraphNodesVisited} nodes)`);
        break;
      }
      if (
        traversed.depth === 0
      ) {
        continue;
      }

      if (
        options.entityTypes &&
        options.entityTypes.length > 0 &&
        !options.entityTypes.includes(
          traversed.entity.type,
        )
      ) {
        continue;
      }

      const graphScore =
        scoreGraphExpansion(
          traversed,
          seed.score,
        );

      const existing =
        resultMap.get(
          traversed.entity.id,
        );

      /*
       * Preserve whichever path gave
       * the strongest score.
       */
      if (
        existing &&
        existing.score >= graphScore
      ) {
        continue;
      }

      resultMap.set(
        traversed.entity.id,
        {
          entity:
            traversed.entity,

          score:
            graphScore,

          matchType:
            "graph",

          depth:
            traversed.depth,

          matchedTerm:
            seed.entity.name,
        },
      );
    }
  }

  /*
   * Include strong lexical matches that
   * weren't among the expansion seeds.
   */
  for (const seed of seeds) {
    const existing =
      resultMap.get(
        seed.entity.id,
      );

    if (
      !existing ||
      seed.score > existing.score
    ) {
      resultMap.set(
        seed.entity.id,
        seed,
      );
    }
  }

  return Array.from(
    resultMap.values(),
  )
    .sort(
      (a, b) =>
        b.score - a.score,
    )
    .slice(0, limit);
}

export function inferHybridWeights(query: string): { vectorWeight: number; graphWeight: number } {
  if (/\b(?:relationship|related|trace|flow|caller|calls?|uses?|depends?|imported?|where is .* defined)\b/i.test(query)) {
    return { vectorWeight: 0.35, graphWeight: 0.65 };
  }
  if (/\b(?:explain|how does|what does|architecture|pipeline)\b/i.test(query)) {
    return { vectorWeight: 0.65, graphWeight: 0.35 };
  }
  return { vectorWeight: 0.6, graphWeight: 0.4 };
}

function reciprocalRankScore(rank: number): number {
  const k = 60;
  return (1 / (k + rank)) / (1 / (k + 1));
}

function normalizeVectorScores(
  results: VectorSearchResult[],
): Map<string, number> {
  const normalized =
    new Map<string, number>();

  if (results.length === 0) {
    return normalized;
  }

  const scores =
    results.map(
      (result) => result.score,
    );

  const max =
    Math.max(...scores);

  const min =
    Math.min(...scores);

  const range =
    max - min;

  for (const result of results) {
    let score = 1;

    if (range > 0) {
      score =
        (result.score - min) /
        range;
    }

    normalized.set(
      result.chunk.id,
      score,
    );
  }

  return normalized;
}

function findChunkForGraphEntity(
  chunks: CodeChunk[],
  filePath: string | undefined,
  name: string,
): CodeChunk | undefined {
  if (!filePath) {
    return undefined;
  }

  return chunks.find(
    (chunk) =>
      chunk.filePath === filePath &&
      chunk.name === name,
  );
}

export function parseRequestedSymbol(query: string): string | undefined {
  return query.match(/\bwhere\s+is\s+([a-z_$][a-z0-9_$]*)\s+(?:implemented|defined|declared|located)\b/i)?.[1];
}

export async function hybridSearch(
  query: string,
  graph: CodeGraph,
  chunks: CodeChunk[],
  vectorResults: VectorSearchResult[],
  options: HybridSearchOptions = {},
): Promise<HybridSearchResult[]> {
  const limit =
    options.limit ?? 10;

  const graphLimit =
    options.graphLimit ?? 15;

  const inferredWeights = inferHybridWeights(query);
  const vectorWeight = options.vectorWeight ?? inferredWeights.vectorWeight;
  const graphWeight = options.graphWeight ?? inferredWeights.graphWeight;

  const graphResults =
    graphSearch(
      graph,
      query,
      {
        limit: graphLimit,
        maxDepth:
          options.graphMaxDepth ?? 2,
      },
    );

  const normalizedVectorScores =
    normalizeVectorScores(
      vectorResults,
    );

  const resultMap =
    new Map<
      string,
      HybridSearchResult
    >();

  /*
   * Add vector results first.
   */
  for (const [vectorIndex, result] of vectorResults.entries()) {
    const normalizedVectorScore =
      normalizedVectorScores.get(
        result.chunk.id,
      ) ?? 0;

    resultMap.set(
      result.chunk.id,
      {
        chunk: result.chunk,

        name:
          result.chunk.name ??
          result.chunk.filePath,

        filePath:
          result.chunk.filePath,

        vectorScore:
          normalizedVectorScore,

        graphScore: 0,

        hybridScore: reciprocalRankScore(vectorIndex + 1) * vectorWeight,

        sources: ["vector"],
      },
    );
  }

  /*
   * Merge GraphRAG results.
   */
  for (const [graphIndex, graphResult] of graphResults.entries()) {
    const matchingChunk =
      findChunkForGraphEntity(
        chunks,
        graphResult.entity.filePath,
        graphResult.entity.name,
      );

    /*
     * Functions/classes usually map
     * directly to chunks.
     *
     * File/module graph nodes may not.
     */
    const key =
      matchingChunk?.id ??
      graphResult.entity.id;

    const existing =
      matchingChunk
        ? resultMap.get(
            matchingChunk.id,
          )
        : resultMap.get(key);

    if (existing) {
      existing.graphScore =
        Math.max(
          existing.graphScore,
          graphResult.score,
        );

      const vectorRank = vectorResults.findIndex((item) => item.chunk.id === matchingChunk?.id);
      existing.hybridScore =
        (vectorRank >= 0 ? reciprocalRankScore(vectorRank + 1) * vectorWeight : 0) +
        reciprocalRankScore(graphIndex + 1) * graphWeight;

      if (
        !existing.sources.includes(
          "graph",
        )
      ) {
        existing.sources.push(
          "graph",
        );
      }

      existing.graphDepth =
        graphResult.depth;

      existing.graphMatchType =
        graphResult.matchType;

      continue;
    }

    resultMap.set(
      key,
      {
        chunk:
          matchingChunk,

        name:
          graphResult.entity.name,

        filePath:
          graphResult.entity.filePath,

        vectorScore: 0,

        graphScore:
          graphResult.score,

        hybridScore: reciprocalRankScore(graphIndex + 1) * graphWeight,

        sources: ["graph"],

        graphDepth:
          graphResult.depth,

        graphMatchType:
          graphResult.matchType,
      },
    );
  }

  return Array.from(
    resultMap.values(),
  )
    .sort(
      (a, b) =>
        b.hybridScore -
        a.hybridScore,
    )
    .slice(0, limit);
}

const getResults = (query: string): readonly RetrievalResult[] => {
