const parseInput = (input: unknown): ReadFileInput => {
  const isObject =
    typeof input === "object" && input !== null && !Array.isArray(input);
  !isObject &&
    (() => {
      throw new Error("Invalid read_file input");
    })();

  const data = input as Record<string, unknown>;
  const rawPath = typeof data.path === "string" ? data.path.trim() : "";
  !rawPath &&
    (() => {
      throw new Error("File path is required");
    })();

  const rawStart =
    typeof data.startLine === "number"
      ? data.startLine
      : Number(data.startLine);
  const startLine = !isNaN(rawStart) && rawStart > 0 ? rawStart : undefined;

  const rawEnd =
    typeof data.endLine === "number" ? data.endLine : Number(data.endLine);
  const endLine = !isNaN(rawEnd) && rawEnd > 0 ? rawEnd : undefined;

  return {
    path: rawPath,
    ...(startLine !== undefined && { startLine }),
    ...(endLine !== undefined && { endLine }),
  };
};

export const createReadFileTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<ReadFileInput, ReadFileOutput> => ({
  name: "read_file",
  description:
    "Reads the text contents of a file in the workspace. Supports optional line range slicing.",
  parameters,
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput,
  execute: async ({ input }) => {
    const filePath = await resolveWorkspaceCandidate(baseDir, input.path, "read");
    const rawContent = await fs.readFile(filePath, "utf8");
    const boundedContent = rawContent.slice(0, MAX_FILE_BYTES);
    const lines = boundedContent.split("\n");
    const totalLines = lines.length;

    const start = Math.max(1, input.startLine ?? 1);
    const end = Math.min(
      totalLines,
      input.endLine ?? Math.min(totalLines, start + MAX_LINES_LIMIT - 1),
    );
    const selectedLines = lines.slice(start - 1, end);

    return {
      path: path.relative(baseDir, filePath).replace(/\\/g, "/"),
      totalLines,
      linesReturned: selectedLines.length,
      content: selectedLines.join("\n"),
    };
  },
});

register<TInput, TOutput>(tool: ToolDefinition<TInput, TOutput>): void {
    this.tools.has(tool.name) &&
      (() => {
        throw new Error(`Tool already registered: ${tool.name}`);
      })();
    this.tools.set(tool.name, tool as unknown as RegisteredTool);
  }

get<TInput, TOutput>(name: string): ToolDefinition<TInput, TOutput> {
    const tool =
      this.tools.get(name) ??
      (() => {
        throw new Error(`Unknown tool: ${name}`);
      })();
    return tool as unknown as ToolDefinition<TInput, TOutput>;
  }

getRuntime(name: string, context: ToolExecutionContext): RuntimeTool {
    const tool =
      this.tools.get(name) ??
      (() => {
        throw new Error(`Unknown tool: ${name}`);
      })();
    this.checkPermissions(tool.permissions, context.userPermissions);
    return {
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
      permissions: tool.permissions,
      timeoutMs: tool.timeoutMs,
      execute: async (input) =>
        tool.execute({
          input: tool.parseInput(input),
          permissions: context.userPermissions,
        }),
    };
  }

list(context?: ToolExecutionContext): readonly RuntimeTool[] {
    const userPermissions = context?.userPermissions ?? [];
    return [...this.tools.values()]
      .filter((tool) => this.hasPermission(tool.permissions, userPermissions))
      .map((tool) => ({
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
        permissions: tool.permissions,
        timeoutMs: tool.timeoutMs,
        execute: async (input) =>
          tool.execute({
            input: tool.parseInput(input),
            permissions: userPermissions,
          }),
      }));
  }

private hasPermission(
    required: readonly ToolPermission[],
    user: readonly ToolPermission[],
  ): boolean {
    return (
      required.length === 0 ||
      (user.length > 0 && required.every((p) => user.includes(p)))
    );
  }

private checkPermissions(
    required: readonly ToolPermission[],
    user: readonly ToolPermission[],
  ): void {
    !this.hasPermission(required, user) &&
      (() => {
        throw new Error(
          `Insufficient permissions for tool. Required: ${required.join(", ")}, User: ${user.join(", ")}`,
        );
      })();
  }

