async executeTool<TOutput>(
    name: string,
    input: unknown,
    context: ToolExecutionContext,
  ): Promise<ToolExecutionResult<TOutput>> {
    const startTime = Date.now();
    const tool = this.tools.get(name);

    if (!tool) {
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: false,
        output: undefined,
        error: `Unknown tool: ${name}`,
        durationMs: Date.now() - startTime,
      };
      logger.warn("Tool execution failed", {
        operation: "tool.execute",
        metadata: {
          ...result,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    }

    this.checkPermissions(tool.permissions, context.userPermissions);

    logger.info("Tool execution started", {
      operation: "tool.execute",
      metadata: {
        toolName: name,
        timeoutMs: tool.timeoutMs,
        tenantId: context.tenantId,
        sessionId: context.sessionId,
      },
    });

    let timer: NodeJS.Timeout | undefined;
    try {
      const parsedInput = tool.parseInput(input);
      const timeoutMs = tool.timeoutMs ?? 30_000;
      const executePromise = tool.execute({
        input: parsedInput,
        permissions: context.userPermissions,
      });

      const timeoutPromise = new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error("Tool execution timeout")),
          timeoutMs,
        );
      });

      const output = await Promise.race([executePromise, timeoutPromise]);
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: true,
        output: output as TOutput,
        error: undefined,
        durationMs: Date.now() - startTime,
      };

      logger.info("Tool execution completed", {
        operation: "tool.execute",
        metadata: {
          toolName: name,
          success: true,
          durationMs: result.durationMs,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    } catch (error) {
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: false,
        output: undefined,
        error: error instanceof Error ? error.message : "Tool execution failed",
        durationMs: Date.now() - startTime,
      };

      logger.error("Tool execution failed", {
        operation: "tool.execute",
        metadata: {
          toolName: name,
          success: false,
          error: result.error,
          durationMs: result.durationMs,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    } finally {
      timer && clearTimeout(timer);
    }
  }

export class ToolRegistry {
  private readonly tools = new Map<string, RegisteredTool>();

  register<TInput, TOutput>(tool: ToolDefinition<TInput, TOutput>): void {
    this.tools.has(tool.name) &&
      (() => {
        throw new Error(`Tool already registered: ${tool.name}`);
      })();
    this.tools.set(tool.name, tool as unknown as RegisteredTool);
  }

  get<TInput, TOutput>(name: string): ToolDefinition<TInput, TOutput> {
    const tool =
      this.tools.get(name) ??
      (() => {
        throw new Error(`Unknown tool: ${name}`);
      })();
    return tool as unknown as ToolDefinition<TInput, TOutput>;
  }

  getRuntime(name: string, context: ToolExecutionContext): RuntimeTool {
    const tool =
      this.tools.get(name) ??
      (() => {
        throw new Error(`Unknown tool: ${name}`);
      })();
    this.checkPermissions(tool.permissions, context.userPermissions);
    return {
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
      permissions: tool.permissions,
      timeoutMs: tool.timeoutMs,
      execute: async (input) =>
        tool.execute({
          input: tool.parseInput(input),
          permissions: context.userPermissions,
        }),
    };
  }

  list(context?: ToolExecutionContext): readonly RuntimeTool[] {
    const userPermissions = context?.userPermissions ?? [];
    return [...this.tools.values()]
      .filter((tool) => this.hasPermission(tool.permissions, userPermissions))
      .map((tool) => ({
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
        permissions: tool.permissions,
        timeoutMs: tool.timeoutMs,
        execute: async (input) =>
          tool.execute({
            input: tool.parseInput(input),
            permissions: userPermissions,
          }),
      }));
  }

  private hasPermission(
    required: readonly ToolPermission[],
    user: readonly ToolPermission[],
  ): boolean {
    return (
      required.length === 0 ||
      (user.length > 0 && required.every((p) => user.includes(p)))
    );
  }

  private checkPermissions(
    required: readonly ToolPermission[],
    user: readonly ToolPermission[],
  ): void {
    !this.hasPermission(required, user) &&
      (() => {
        throw new Error(
          `Insufficient permissions for tool. Required: ${required.join(", ")}, User: ${user.join(", ")}`,
        );
      })();
  }

  async executeTool<TOutput>(
    name: string,
    input: unknown,
    context: ToolExecutionContext,
  ): Promise<ToolExecutionResult<TOutput>> {
    const startTime = Date.now();
    const tool = this.tools.get(name);

    if (!tool) {
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: false,
        output: undefined,
        error: `Unknown tool: ${name}`,
        durationMs: Date.now() - startTime,
      };
      logger.warn("Tool execution failed", {
        operation: "tool.execute",
        metadata: {
          ...result,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    }

    this.checkPermissions(tool.permissions, context.userPermissions);

    logger.info("Tool execution started", {
      operation: "tool.execute",
      metadata: {
        toolName: name,
        timeoutMs: tool.timeoutMs,
        tenantId: context.tenantId,
        sessionId: context.sessionId,
      },
    });

    let timer: NodeJS.Timeout | undefined;
    try {
      const parsedInput = tool.parseInput(input);
      const timeoutMs = tool.timeoutMs ?? 30_000;
      const executePromise = tool.execute({
        input: parsedInput,
        permissions: context.userPermissions,
      });

      const timeoutPromise = new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error("Tool execution timeout")),
          timeoutMs,
        );
      });

      const output = await Promise.race([executePromise, timeoutPromise]);
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: true,
        output: output as TOutput,
        error: undefined,
        durationMs: Date.now() - startTime,
      };

      logger.info("Tool execution completed", {
        operation: "tool.execute",
        metadata: {
          toolName: name,
          success: true,
          durationMs: result.durationMs,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    } catch (error) {
      const result: ToolExecutionResult<TOutput> = {
        toolName: name,
        callId: crypto.randomUUID(),
        success: false,
        output: undefined,
        error: error instanceof Error ? error.message : "Tool execution failed",
        durationMs: Date.now() - startTime,
      };

      logger.error("Tool execution failed", {
        operation: "tool.execute",
        metadata: {
          toolName: name,
          success: false,
          error: result.error,
          durationMs: result.durationMs,
          tenantId: context.tenantId,
          sessionId: context.sessionId,
        },
      });
      return result;
    } finally {
      timer && clearTimeout(timer);
    }
  }
}

const parseInput = (input: unknown): RetrievalRequest => {
  const isObject =
    typeof input === "object" && input !== null && !Array.isArray(input);
  !isObject &&
    (() => {
      throw new Error("Invalid knowledge tool input");
    })();

  const data = input as Record<string, unknown>;
  const query = data.query;

  typeof query !== "string" &&
    (() => {
      throw new Error("Knowledge query must be a string");
    })();

  const normalizedQuery = (query as string).trim();
  !normalizedQuery &&
    (() => {
      throw new Error("Knowledge query must not be empty");
    })();

  const tenantId =
    typeof data.tenantId === "string" ? data.tenantId.trim() : undefined;
  const limit =
    typeof data.limit === "number" &&
      Number.isInteger(data.limit) &&
      data.limit > 0
      ? data.limit
      : undefined;

  return {
    query: normalizedQuery,
    ...(tenantId && { tenantId }),
    ...(limit !== undefined && { limit }),
  };
};

