export const sanitizeWorkspacePath = (
  baseDir: string,
  requestedPath: string,
  op: ToolOperationType = "read",
): string => {
  const containsNull = requestedPath.includes("\0");
  containsNull &&
    (() => {
      throw new Error("Path contains illegal null bytes");
    })();

  const filename = path.basename(requestedPath);
  const lowerFilename = filename.toLowerCase();

  if (op === "read") {
    const isSensitive = SENSITIVE_READ_PATTERNS.some((pattern) =>
      pattern.test(requestedPath),
    );
    if (isSensitive) {
      throw new Error("Access denied: reading sensitive file is prohibited");
    }
  } else if (op === "write") {
    const isProtectedWrite =
      PROTECTED_WRITE_FILES.has(filename) ||
      PROTECTED_WRITE_FILES.has(lowerFilename) ||
      lowerFilename.startsWith(".env");
    if (isProtectedWrite) {
      throw new Error(
        "Access denied: writing to protected system file is disallowed",
      );
    }
  } else if (op === "delete") {
    const isProtectedDelete =
      PROTECTED_DELETE_FILES.has(filename) ||
      PROTECTED_DELETE_FILES.has(lowerFilename) ||
      lowerFilename.startsWith(".env");
    if (isProtectedDelete) {
      throw new Error(
        "Access denied: deleting protected project file is prohibited",
      );
    }
  }

  const resolved = path.resolve(baseDir, requestedPath);
  const relative = path.relative(baseDir, resolved);
  const isEscaping = relative.startsWith("..") || path.isAbsolute(relative);
  if (isEscaping) {
    throw new Error("Access denied: path escapes workspace root");
  }

  if (op === "delete") {
    const isProtectedDir = PROTECTED_DELETE_DIRS.has(
      relative.replace(/\\/g, "/"),
    );
    if (isProtectedDir) {
      throw new Error(
        "Access denied: deleting root system directory is prohibited",
      );
    }
  }

  return resolved;
};

const findFileInWorkspace = async (
  dir: string,
  targetFilename: string,
  depth = 0,
): Promise<string | null> => {
  if (depth > 5) return null;

  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory()) {
        if (EXCLUDED_SCAN_DIRS.has(entry.name) || entry.name.startsWith(".")) {
          continue;
        }
        const found = await findFileInWorkspace(
          path.join(dir, entry.name),
          targetFilename,
          depth + 1,
        );
        if (found) return found;
      } else if (entry.isFile() && entry.name === targetFilename) {
        return path.join(dir, entry.name);
      }
    }
  } catch {
    // Ignore unreadable directories
  }

  return null;
};

export const resolveWorkspaceCandidate = async (
  baseDir: string,
  requestedPath: string,
  op: ToolOperationType = "read",
): Promise<string> => {
  const directPath = sanitizeWorkspacePath(baseDir, requestedPath, op);

  try {
    await fs.access(directPath);
    return directPath;
  } catch {
    const filename = path.basename(requestedPath);
    if (
      filename &&
      !requestedPath.includes("/") &&
      !requestedPath.includes("\\")
    ) {
      const match = await findFileInWorkspace(baseDir, filename);
      if (match) {
        return match;
      }
    }
    return directPath;
  }
};

const extractString = (
  data: Record<string, unknown>,
  keys: readonly string[],
): string => {
  for (const key of keys) {
    if (
      typeof data[key] === "string" &&
      (data[key] as string).length > 0
    ) {
      return data[key] as string;
    }
  }
  return "";
};

const parseInput = (input: unknown): WriteFileInput => {
  const isObject =
    typeof input === "object" && input !== null && !Array.isArray(input);
  !isObject &&
    (() => {
      throw new Error("Invalid write_file input");
    })();

  const data = input as Record<string, unknown>;
  const rawPath = extractString(data, [
    "path",
    "filePath",
    "file_path",
    "filename",
    "file",
  ]).trim();
  !rawPath &&
    (() => {
      throw new Error("File path is required");
    })();

  const rawContent = extractString(data, [
    "content",
    "text",
    "file_content",
    "body",
    "code",
  ]);
  const overwrite =
    typeof data.overwrite === "boolean" ? data.overwrite : true;

  return { path: rawPath, content: rawContent, overwrite };
};

export const createWriteFileTool = (
  baseDir: string = process.cwd(),
): ToolDefinition<WriteFileInput, WriteFileOutput> => ({
  name: "write_file",
  description:
    "Creates or writes text content to a file in the workspace.",
  parameters,
  permissions: DEFAULT_PERMISSIONS,
  timeoutMs: DEFAULT_TIMEOUT_MS,
  parseInput,
  execute: async ({ input }) => {
    const filePath = await resolveWorkspaceCandidate(baseDir, input.path, "write");
    const byteLength = Buffer.byteLength(input.content, "utf8");

    byteLength > MAX_ALLOWED_BYTES &&
      (() => {
        throw new Error(
          `Content size ${byteLength} bytes exceeds limit of ${MAX_ALLOWED_BYTES} bytes`,
        );
      })();

    if (!input.overwrite) {
      try {
        await fs.access(filePath);
        throw new Error(`File '${input.path}' already exists`);
      } catch (err: unknown) {
        if ((err as NodeJS.ErrnoException).code !== "ENOENT") throw err;
      }
    }

    await fs.mkdir(path.dirname(filePath), { recursive: true });
    await fs.writeFile(filePath, input.content, "utf8");

    return {
      path: input.path,
      created: true,
      bytesWritten: byteLength,
      message: `Successfully wrote ${byteLength} bytes to '${input.path}'.`,
    };
  },
});

