 * - clarify        : Insufficient information to act — ask user for clarification
 * - refuse         : Request is unsafe, destructive, or prohibited — politely refuse
 */
export type AgentAction =
  | "direct_answer"
  | "retrieve"
  | "tool"
  | "clarify"
  | "refuse";

